//岛屿对象
let CIsland = function(node, id) {
    this.node = node;
    this.id = id;
    this.spine = cc.find("spine", node);
    this.spine_light = cc.find("spine_light", node);
    this.spine_stroke = cc.find("spine_stroke", node);
    this.treasurebox_normal = cc.find("treasurebox", node);
    this.spine_treasurebox = cc.find("spine_treasurebox", node);
    this.spine_treasurebox.active = false;

    this.treasurebox_open = cc.find("treasurebox_open", node);
    this.treasurebox_open.active = false;

    this.isEnabled = false;

    //设置点击回调
    this.setClickCallback = function (callback) {
        Global.btnClickEvent(this.node, ()=>{
           Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);
            callback(this);
        }, this);
    };

    //设置是否可选择状态
    this.setEnabled = function (isEnable) {
        this.isEnabled = isEnable;
        this.setLightActive(isEnable);
        if (isEnable) {
            this.setGray(false);
            this.setStrokeActive(false);
        }
    };

    //设置灰色
    this.setGray = function (isGray) {
        let color = isGray?cc.Color.GRAY:cc.Color.WHITE;
        for (let node of this.node.children) {
            node.color = color;
        }

        if (isGray) {
            this.setLightActive(false);
            this.setStrokeActive(false);
            // this.setBoxNormal(true);
        }
    };

    //设置光晕显示
    this.setLightActive = function (isActive) {
        this.spine_light.active = isActive;
    };

    //设置描边显示
    this.setStrokeActive = function (isActive) {
        this.spine_stroke.active = isActive;
    };

    //设置宝箱状态
    this.setBoxNormal = function (isNormal) {
        this.treasurebox_normal.active = isNormal;
        this.treasurebox_open.active = !isNormal;
    };
};


cc.Class({
    extends: cc.Component,

    properties: {
        // machine         : {
        //     default : null,
        //     visible : false
        // }, // 状态机

        _mapNode: null,
        _mapPathNode: null,

        _moveUser: null,

        _islandArr: null,
        _mapPointArr: null,
        _curIslandId:0,
        _mIsLandCallback: null, //用于流程回归

        _isLook: false, //是查看状态

        //当前位置

    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        //隐藏所有子节点
        for (let subNode of this.node.children) subNode.active = false;

        this._mapNode = cc.find("mapMain", this.node);

        this._mapPathNode = cc.find("nodeMapPath", this._mapNode);
        this._moveUser = cc.find("theme163_map_user", this._mapPathNode);
        this._islandArr = [];
        for (let i=1; i<=6; i++) {
            let isLandObj = new CIsland(cc.find("theme163_map_dao" + i, this._mapPathNode), i);
            this._islandArr.push(isLandObj);
            isLandObj.setClickCallback(this.onIslandClicked.bind(this));
        }
        this._mapPointArr = [];
        for (let i=1; i<=10; i++) {
            let road = cc.find("theme163_map_road" + i, this._mapPathNode);
            road.getComponent(cc.Sprite).enabled = false;
            road.getChildByName("spine").active = false;
            for (let point of road.children) {
                if (point.name != 'spine') this._mapPointArr[parseInt(point.name.substr(-2,2))] = point;
            }
        }

        //choose island YES
        Global.btnClickEvent(cc.find("uiChooseIslandSureTips/ui/btnYES", this._mapNode), this.onChooseYES.bind(this), this);
        //choose island NO
        Global.btnClickEvent(cc.find("uiChooseIslandSureTips/ui/btnNO", this._mapNode), this.onChooseNO.bind(this), this);

        //帮助按钮
        Global.btnClickEvent(cc.find("btnHelp", this._mapNode), ()=>{
           Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);

            let uiHelp = cc.find("uiHelp", this._mapNode);
            uiHelp.active = !uiHelp.active;
            uiHelp.stopAllActions();
            uiHelp.runAction(cc.sequence(cc.delayTime(3.0), cc.callFunc(()=>{
                uiHelp.active = false;
            })))

            Global.btnClickEvent(uiHelp, ()=>{
                Global.SlotsSoundMgr.playEffect(Global.SlotsSoundMgr.common_click);

                uiHelp.stopAllActions();
                uiHelp.active = false;
            }, this);
        }, this);

        //返回游戏按钮
        Global.btnClickEvent(cc.find("backToGame", this._mapNode), ()=>{
            this.moveupMap();
        }, this);

        /** @type {TheMermaid_subGameBase} **/
        this._bekeGameCmp = this.addComponent("TheMermaid_subGameBeke");
        // this._bekeGameCmp.machine = this.machine;

        /** @type {TheMermaid_subGameYellowFish} **/
        this._yellowFishGameCmp = this.addComponent("TheMermaid_subGameYellowFish");
        // this._yellowFishGameCmp.machine = this.machine;

        /** @type {TheMermaid_subGameDice} **/
        this._diceGameCmp = this.addComponent("TheMermaid_subGameDice");
        // this._diceGameCmp.machine = this.machine;

        /** @type {TheMermaid_subGameMultWheel} **/
        this._multWheelGameCmp = this.addComponent("TheMermaid_subGameMultWheel");
        // this._multWheelGameCmp.machine = this.machine;

        /** @type {TheMermaid_subGameRenyu} **/
        this._renyuGameCmp = this.addComponent("TheMermaid_subGameRenyu");
        // this._renyuGameCmp.machine = this.machine;

        /** @type {TheMermaid_subGameGoldShip} **/
        this._goldShipGameCmp = this.addComponent("TheMermaid_subGameGoldShip");
        // this._goldShipGameCmp.machine = this.machine;

        /** @type {TheMermaid_CollectWheel} **/
        this._collectWheelCmp = this.addComponent("TheMermaid_subGameCollectWheel");
        // this._collectWheelCmp.machine = this.machine;

        //自动适配
        this.autoAdaptSize();
    },

    //自动适配
    autoAdaptSize() {
        return;
        let canvasNode = cc.find('Canvas');
        var canvasWidth = canvasNode.width;
        var canvasHeight = canvasNode.height;
        if (canvasNode) {
            var designWidth = 720;
            var designHeight = 1560;
            let xScale = canvasWidth/designWidth;
            let yScale = canvasHeight/designHeight;
            this.node.scale = Math.min(xScale, yScale); //按照较小的缩放
        }
    },

    async start () {
        this.restoreMapByData();
        //断线重连
        if (cc.vv.gameData.mapInfo.state != Global.QUEENOFSEA_MAP_STATE.COLLECT_ENERGY) {
            //非收集能量步骤，断线重连
            this.enterMap(false, false);
        }
    },

    //恢复地图
    restoreMapByData () {
        let mapInfo = cc.vv.gameData.mapInfo;

        //是否显示返回游戏按钮
        cc.find("backToGame", this._mapNode).active = this._isLook;
        //初始状态
        for (let i=0;i<6; i++) {
            //已完成岛屿
            let complete_island = cc.find("nodePrizePool/complete_island_" + (i + 1), this._mapNode);
            if (complete_island) complete_island.active = false;
            //隐藏岛屿名字提示
            this.setIslandTipsActive(i + 1, false);
            //隐藏光圈
            this._islandArr[i].setEnabled(false);
            //控制描边
            this._islandArr[i].setStrokeActive(false);
            //控制灰色
            this._islandArr[i].setGray(true);
        }

        //岛屿显示
        for (let i in mapInfo.completeGame) {
            let isLandId = mapInfo.completeGame[i];
            this._islandArr[isLandId - 1].setGray(false); //点亮
            this._islandArr[isLandId - 1].setBoxNormal(false); //宝箱开启状态

            let spIsland = cc.find("nodePrizePool/complete_island_" + (parseInt(i) + 1), this._mapNode);
            spIsland.active = true;
            spIsland.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("map").getSpriteFrame("theme163_map_over_sp" +  COMPLETE_SP[isLandId]);
        }

        //下一个岛屿
        if (mapInfo.nextGame > 0) {
            this._islandArr[mapInfo.nextGame - 1].setGray(false); //点亮
            this._islandArr[mapInfo.nextGame - 1].setStrokeActive(true); //点亮
        }

        //线路显示
        for (let i=1; i<=10; i++) cc.find("theme163_map_road" + i, this._mapPathNode).getComponent(cc.Sprite).enabled = false;
        let roadNode = this.getCurRoadNode();
        if (roadNode) roadNode.getComponent(cc.Sprite).enabled = true;

        //moveUser显示
        let nextStepNode = this.getNextStepNode();
        if (nextStepNode && !cc.vv.gameData._gameInfo) this._moveUser.position = this.convertNodePosToLocalPos(nextStepNode, this._moveUser.parent);
    },

    //进入地图
    async enterMap (isLook, isMoveDown) {
        this._isLook = isLook;
        this._bTriggerSubGame = false;
        Global.dispatchEvent(EventId.QUEEN_ENTER_MAP);

        this.restoreMapByData(this._isLook);

        return new Promise(async (success)=>{
            //地图下拉
            if (isMoveDown) {
                await this.movedownMap();
            }
            else {
                this._mapNode.y = 0;
                this._mapNode.active = true;
            }
            if (!isLook) {
                //走下一步
                await this.nextStep();
                //显示收集数转盘
                await this.showCollectWheel();
                //退出地图
                await this.exitMap();
            }
            success();
        });
    },

    //退出地图
    async exitMap() {
       await this.moveupMap();
    },

    isTriggerSubGame()  {
        return this._bTriggerSubGame;
    },

    //小鱼走一步
    async nextStep() {
        return new Promise(async (success)=>{
            //移动到下一步
            await this.moveNextStep();
            //选择下一个子游戏
            await this.chooseNextSubGame();
            //触发子游戏
            await this.triggerSubGame();
            success();
        });
    },

    //获取当前Road数据
    getCurRoadData () {
        let mapInfo = cc.vv.gameData.mapInfo;
        let prevGame = mapInfo.prevGame || 6; //prevGame==0表示刚开始转圈
        let nextGame = mapInfo.nextGame;
        let curRoadData = MapPathCfg[prevGame][nextGame];
        return curRoadData;
    },

    //获取当前Road节点
    getCurRoadNode () {
        let curRoadData = this.getCurRoadData();
        let road = null;
        if (curRoadData) road = cc.find("theme163_map_road" + curRoadData[0], this._mapPathNode);
        return road;
    },

    //获取下一步节点
    getNextStepNode () {
        let mapInfo = cc.vv.gameData.mapInfo;
        let curRoadData = this.getCurRoadData();
        if (mapInfo.restStep == 0) { //岛
            if (mapInfo.prevGame == 0 && mapInfo.nextGame == 0) {//表示刚开始进入地图，选择5个地图
                return this._islandArr[Global.QUEENOFSEA_SUBGAME.GOLDSHIP - 1].node; //黄金船岛
            }
            return this._islandArr[mapInfo.nextGame - 1].node;
        }
        else { //路径点
            let pointArr = curRoadData[1];
            return this._mapPointArr[pointArr[pointArr.length - mapInfo.restStep]];
        }
    },

    //移动到下一步
    async moveNextStep () {
        return new Promise(async (success)=>{
            //获取下一步节点
            let nextStepNode = this.getNextStepNode();
            if (nextStepNode) {
                //鱼移动音效
               Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.move);
                await this.playActions(this._moveUser, [cc.moveTo(0.8, this.convertNodePosToLocalPos(nextStepNode, this._moveUser.parent))]);
                await this.awaitTime(1.0);
            }
            success();
        });
    },

    convertNodePosToLocalPos (node, localNode) {
        return localNode.convertToNodeSpaceAR(node.parent.convertToWorldSpaceAR(node.position));
    },

    async popUIChooseIslandTips () {
        return new Promise(async success=>{
            //是否显示选择岛屿
            let uiTips = cc.find("uiChooseIslandTips", this._mapNode);
            uiTips.active = true;
            await this.setUIVisible(cc.find("ui", uiTips), true);

            let btnGo = cc.find("ui/btnLetsGo", uiTips);
            btnGo.off("click");

            let self = this;
            let func = async ()=>{
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);
                btnGo.stopAllActions();

                await self.setUIVisible(cc.find("ui", uiTips), false);
                uiTips.active = false;

                let tips = cc.find("chooseIslandTips", self._mapPathNode);
                tips.active = true;
                tips.stopAllActions();
                tips.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(0.5,0.9), cc.scaleTo(0.2,1.0), cc.delayTime(2.0))));

                success();
            };
            cc.vv.gameData.checkAutoPlay(btnGo, func);
            //Let`s go
            Global.btnClickEvent(btnGo, async ()=>{
                func();
            }, this);
        });
    },

    findIslandToEnable () {
        let mapInfo = cc.vv.gameData.mapInfo;
        let nextGame = mapInfo.nextGame || 6;
        let nextGameList = MapPathCfg[nextGame];
        for (let i in nextGameList) {
            if (parseInt(i) === 6) { //去中心岛
                if (mapInfo.completeGame.length < 5) { //未走完，不可去
                    continue;
                }
            }

            let island =  this._islandArr[parseInt(i) - 1];
            island.setEnabled(true); //可操作
        }
    },

    //选择子游戏
    async chooseNextSubGame() {
        return new Promise(async (success)=>{
            let state = cc.vv.gameData.mapInfo.state;
            if (state == Global.QUEENOFSEA_MAP_STATE.CHOOSE_SUBGAME) {
                //选择提示
                this.popUIChooseIslandTips();
                //隐藏所有线路
                for (let i=1; i<=10; i++) cc.find("theme163_map_road" + i, this._mapPathNode).getComponent(cc.Sprite).enabled = false;
                //所有岛屿
                for (let i=0; i<6; i++) {
                    //不可操作
                    this._islandArr[i].setEnabled(false);
                    //控制描边
                    this._islandArr[i].setStrokeActive(false);
                    //控制灰色
                    this._islandArr[i].setGray(true);
                }
                //根据当前位置找出所有可供选择的岛屿，并显示可选岛屿
                this.findIslandToEnable();
                //根据选择请求数据
                this._mIsLandCallback = async ()=>{
                    //请求选择岛屿
                    let resp = await cc.vv.gameData.reqSubGame(Global.QUEENOFSEA_MAP_RTYPE.CHOOSE_SUBGAME, this._curIslandId);
                    if (resp.code === 200) {
                        let road = this.getCurRoadNode();
                        road.getComponent(cc.Sprite).enabled = true;

                        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.path);

                        this.playSpine(road.getChildByName("spine"), null, MapRoadCfg[this.getCurRoadData()[0] - 1].lightAnim, false);

                        //继续下一步
                        success ();
                    }
                    else {
                        AppLog.err("请求数据错误");
                    }
                }
            }
            else {
                success();
            }
        });
    },

    //判断是否进入子游戏
    async triggerSubGame () {
        return new Promise(async (success)=>{
            let state = cc.vv.gameData.mapInfo.state;
            //触发游戏
            if (state == Global.QUEENOFSEA_MAP_STATE.ENTER_SUBGAME) {
                let gameId = cc.vv.gameData.mapInfo.nextGame;
                let isEnterSubGame = true;
                switch (gameId) {
                    case Global.QUEENOFSEA_SUBGAME.BEKE:  //贝壳
                        await this.getBekeCmp().enterGame();
                        break;
                    case Global.QUEENOFSEA_SUBGAME.YELLOW_FISH:  //小黄鱼
                        await this.getYellowFishCmp().enterGame();
                        break;
                    case Global.QUEENOFSEA_SUBGAME.DICE:  //骰子
                        await this.getDiceCmp().enterGame();
                        break;
                    case Global.QUEENOFSEA_SUBGAME.WHEEL:  //轮盘
                        await this.getMultWheelCmp().enterGame();
                        break;
                    case Global.QUEENOFSEA_SUBGAME.RENYU:  //人鱼
                        await this.getRenyuCmp().enterGame();
                        break;
                    case Global.QUEENOFSEA_SUBGAME.GOLDSHIP: //黄金船
                        await this.getGoldShipCmp().enterGame();
                        //一轮完成
                        cc.vv.gameData.mapInfo.completeGame = [];
                        this.restoreMapByData();
                        break;
                    default:
                        isEnterSubGame = false;
                        break;
                }

                //进入过子游戏
                if (isEnterSubGame) {
                    this._bTriggerSubGame = true;

                    // 开宝箱,飞Complete标识
                    let completeGames = cc.vv.gameData.mapInfo.completeGame;
                    if (gameId == completeGames[completeGames.length - 1]) {
                        let spIsland = cc.find("nodePrizePool/complete_island_" + completeGames.length, this._mapNode);
                        spIsland.active = true;
                        spIsland.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("map").getSpriteFrame("theme163_map_over_sp" + COMPLETE_SP[gameId]);
                        let oldPos = spIsland.position;
                        spIsland.position = spIsland.parent.convertToNodeSpace(this._mapPathNode.convertToWorldSpace(this._islandArr[gameId - 1].node.position));
                        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.map_collect);
                        await this.playActions(spIsland, [cc.moveTo(0.5, oldPos)]);
                        this.playSpine(spIsland.getChildByName("spine"), null, "animation", false);
                        await this.awaitTime(0.5);
                    }

                    //弹出提示选择岛屿以及选择岛屿
                    await this.chooseNextSubGame();
                }
            }

            success();
        });
    },

    //显示收集数转盘
    async showCollectWheel () {
        return new Promise(async (success)=>{
            let state = cc.vv.gameData.mapInfo.state;
            if (state == Global.QUEENOFSEA_MAP_STATE.COLLECT_WHEEL) {
                await this.getCollectWheelCmp().enterGame();

                //设置进度条
                SlotsFacade.QueenSeaCollectProgress.setProgress(0);
            }
            success();
        });
    },

    async setUIVisible (ui, isVisible) {
        return new Promise(async (success)=>{
            if (ui.active == isVisible) success();
            if (isVisible) {
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.tips);

                ui.scale = 0;
                ui.active = isVisible;
                this.playActions(ui, [cc.scaleTo( 0.3, 1.2), cc.scaleTo(0.1, 1.0)]);
            }
            else {
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.tips_close);

                ui.scale = 1.0;
                this.playActions(ui, [cc.scaleTo(0.1, 1.2), cc.scaleTo(0.3, 0), cc.callFunc(()=>{
                    ui.active = isVisible;
                })]);
            }
            success();
        });
    },

    //地图下拉
    async movedownMap() {
        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.map_open);

        await this.playActions(this._mapNode, [
            cc.callFunc(()=>{
                this._mapNode.y = (this.node.height + this._mapNode.height)/2;
            }),
            cc.delayTime(0.05),
            cc.moveTo(0.5, cc.v2(0,0))
        ]);
    },

    //地图上移隐藏
    async moveupMap() {
        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.map_close);

        await this.playActions(this._mapNode, [
            cc.callFunc(()=>{
                this._mapNode.y = 0;
            }),
            cc.moveTo(0.5, cc.v2(0,(this.node.height + this._mapNode.height)/2)),
            cc.callFunc(()=>{
                Global.dispatchEvent(EventId.QUEEN_EXIT_MAP);
            })
        ]);
    },

    //岛屿点击
    onIslandClicked (islandObj) {
        if (islandObj.isEnabled) { //选择岛屿
            this._curIslandId = islandObj.id;

            //岛屿状态
            for (let i=0; i<6; i++) this._islandArr[i].setEnabled(false);
            this._islandArr[this._curIslandId - 1].setStrokeActive(true);

            //隐藏提示
            cc.find("chooseIslandTips", this._mapPathNode).active = false;
            //弹出选择确认
            this.setUIChooseIslandSureTipsVisible(true);
        }
        else {
            this.setIslandTipsActive(islandObj.id, true);
        }
    },

    setUIChooseIslandSureTipsVisible (isVisible) {
        let uiChooseIslandSureTips = cc.find("uiChooseIslandSureTips", this._mapNode);
        for (let i=1; i<=6; i++) cc.find("ui/theme163_d_choose_type" + i, uiChooseIslandSureTips).active = (i == this._curIslandId);

        if (isVisible) {
            let btnYES = cc.find("uiChooseIslandSureTips/ui/btnYES", this._mapNode);
            btnYES.getComponent(cc.Button).enabled = true;
            let btnNO = cc.find("uiChooseIslandSureTips/ui/btnNO", this._mapNode);
            btnNO.getComponent(cc.Button).enabled = true;

            uiChooseIslandSureTips.active = isVisible
            this.setUIVisible(uiChooseIslandSureTips.getChildByName("ui"), true);

            cc.vv.gameData.checkAutoPlay(btnYES, this.onChooseYES.bind(this));
        }
        else {
            this.setUIVisible(uiChooseIslandSureTips.getChildByName("ui"), false);
            uiChooseIslandSureTips.runAction(cc.sequence(cc.delayTime(0.5), cc.callFunc(()=>{
                uiChooseIslandSureTips.active = isVisible
            })));
        }
    },

    onChooseYES () {
        let btnYES = cc.find("uiChooseIslandSureTips/ui/btnYES", this._mapNode);
        btnYES.getComponent(cc.Button).enabled = false;
        let btnNO = cc.find("uiChooseIslandSureTips/ui/btnNO", this._mapNode);
        btnNO.getComponent(cc.Button).enabled = false;
        btnYES.stopAllActions();

        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);

        this.setUIChooseIslandSureTipsVisible(false);
        this._mIsLandCallback(); //回到原选择岛屿有流程 chooseNextSubGame
    },

    onChooseNO () {
        let btnYES = cc.find("uiChooseIslandSureTips/ui/btnYES", this._mapNode);
        btnYES.getComponent(cc.Button).enabled = false;
        let btnNO = cc.find("uiChooseIslandSureTips/ui/btnNO", this._mapNode);
        btnNO.getComponent(cc.Button).enabled = false;
        btnYES.stopAllActions();

        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);

        this.setUIChooseIslandSureTipsVisible(false);
        //根据当前位置找出所有可供选择的岛屿，并显示可选岛屿
        this.findIslandToEnable();
        //选择提示
        cc.find("chooseIslandTips", this._mapPathNode).active = true;
    },

    //设置提示是否可见
    setIslandTipsActive (id, active) {
        let islandTips = cc.find("islandTips" + id, this._mapPathNode);
        islandTips.active = active;
        islandTips.stopAllActions();
        islandTips.runAction(cc.sequence(cc.delayTime(3.0), cc.callFunc(()=>{
            islandTips.active = false;
        })));
    },

    playSpine (node, endCall, animationName="animation", isLoop=false) {
        if (node) {
            node.active = true;
            node.getComponent(sp.Skeleton).setAnimation(0, animationName, isLoop);
            if (!isLoop) {
                node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    if (endCall) endCall();
                });
            }
        }
        else {
            if (endCall) endCall();
        }
    },

    playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.stopAllActions();
            node.runAction(cc.sequence(actionsArr));
        });
    },

    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },

    /**
     * 贝壳关卡游戏
     * @returns {TheMermaid_subGameBase}
     */
    getBekeCmp() {
        return this._bekeGameCmp;
    },

    /**
     * 小黄鱼（珊瑚）关卡游戏
     * @returns {TheMermaid_subGameYellowFish}
     */
    getYellowFishCmp() {
        return this._yellowFishGameCmp;
    },

    /**
     * 骰子关卡游戏
     * @returns {TheMermaid_subGameDice}
     */
    getDiceCmp() {
        return this._diceGameCmp;
    },

    /**
     * 轮子关卡游戏
     * @returns {TheMermaid_subGameMultWheel}
     */
    getMultWheelCmp() {
        return this._multWheelGameCmp;
    },

    /**
     * 黄金船宝箱关卡游戏
     * @returns {TheMermaid_subGameGoldShip}
     */
    getGoldShipCmp() {
        return this._goldShipGameCmp;
    },

    /**
     * 人鱼关卡游戏
     * @returns {TheMermaid_subGameRenyu}
     */
    getRenyuCmp() {
        return this._renyuGameCmp;
    },

    /**
     * 收集转盘
     * @returns {TheMermaid_subGameCollectWheel}
     */
    getCollectWheelCmp() {
        return this._collectWheelCmp;
    },

});
