let BUBBLE_ANIMATION = [
    "3",
    "1",
    "4",
    "2",
    "5",
];


cc.Class({
    extends: require("TheMermaid_subGameBase"),

    properties: {
        _subGameNodeName: "subGameYellowFish",

        _lblStartPrize: null,
        _sprPickTips: null,

        _roralsFishList: null,
        _winList: null,

        _chooseCount: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._super();

        this._lblStartPrize = cc.find("nodePrizePool/theme163_game_c_2/lblStartPrize", this._node_main);
        this._sprPickTips = cc.find("nodeDetail/pickTips", this._node_main);

        this._roralsFishList = [];
        this._winList = [];
        for (let i=1; i<=5; i++) {
            this._roralsFishList[i] = cc.find("nodeDetail/fish/fish" + i, this._node_main);
            this._winList[i] = cc.find("nodeDetail/win/win" + i, this._node_main);
        }

        this.init();
    },

    init () {
        for (let i=1; i<=5; i++) {
            this._winList[i].active = false;

            let roralhNode = this._roralsFishList[i];
            roralhNode.getComponent(cc.Button).enabled = true;

            let parrot = roralhNode.getChildByName("spineParrot");
            parrot.active = true;
            this.playSpine(parrot, null, "animation1", true);

            let bubble = roralhNode.getChildByName("spineBubble");
            bubble.active = false;
        }

        for (let node of cc.find("nodeDetail/mult", this._node_main).children) {
            node.active = false;
        }
    },

    restoreByData () {
        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;

        this._subGameNode.active = true;
        this._chooseCount = gameInfo.useCnt;

        //i对应珊瑚 对应值是选中小鱼
        for (let i in gameInfo.coral) {
            let roralIdx = parseInt(i) + 1;
            let winIdx = gameInfo.coral[i];

            let roralhNode = this._roralsFishList[roralIdx];
            roralhNode.getComponent(cc.Button).enabled = winIdx == 0;

            let parrot = roralhNode.getChildByName("spineParrot");
            parrot.active = winIdx == 0;
            this.playSpine(parrot, null, "animation1", true);

            let bubble = roralhNode.getChildByName("spineBubble");
            bubble.active = winIdx != 0;
            if (winIdx != 0) this.playSpine(bubble, null, "animation" + BUBBLE_ANIMATION[winIdx - 1] + "_1", true);

            if (winIdx > 0) this._winList[winIdx].active = true;
        }
    },

    //进入游戏
    async enterGame () {
        this.init();

        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
        this._chooseCount = gameInfo.useCnt || 0;
        this.setLabel(this._lblStartPrize, Global.FormatNumToComma(gameInfo.startPrize));

        return new Promise(async (success)=>{
            //根据数据恢复显示
            this.restoreByData();
            if (this._chooseCount == 0) { //刚进入
                await this.showStart();
            }
            await this.showMain();
            await this.showResult();
            await this.exitGame();
            success();
        });
    },

    //退出游戏
    async exitGame () {
        return new Promise(async (success)=>{
            //全屏过渡
            await this.playFullScreen(1.0);
            this.setSubGameNodeVisible(false);
            success();
        });
    },

    //显示开始提示
    async showStart () {
        return new Promise(async (success)=>{
            this._subGameNode.active = true;
            this._node_start.active = true;
            this._node_start.scale = 0;
            await this.playActions(this._node_start, [cc.scaleTo(0.35, 1.5), cc.scaleTo(0.15, 1.3)]);
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);
                this.playActions(this._node_start, [cc.scaleTo(0.15, 1.5), cc.scaleTo(0.35, 0)]);
                success();
            }
            cc.vv.gameData.checkAutoPlay(this._node_start.getChildByName("btnStart"), func);
            Global.btnClickEvent(this._node_start.getChildByName("btnStart"), ()=>{
                this._node_start.getChildByName("btnStart").stopAllActions();
                func();
            }, this);
        });
    },

    //显示游戏主体
    async showMain () {
        return new Promise(async (success)=>{
            //全屏过渡
            let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
            if (gameInfo.mult <= 0) await this.playFullScreen(0.5);
            //初始化
            this._node_start.active = false;
            this._node_main.active = true;
            await this.awaitTime(0.2);
            //等待玩家选择操作
            await this.awaitOrOperate();
            //等待操作提示
            this.setPlayPickTipsAction(false);
            //等待
            await this.awaitTime(1.0);
            success();
        });
    },

    setPlayPickTipsAction (isPlay) {
        if (isPlay) {
            this._sprPickTips.scale = 1.0;
            this._sprPickTips.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(0.5,0.9), cc.scaleTo(0.2,1.0), cc.delayTime(2.0))));
        }
        else {
            this._sprPickTips.stopAllActions();
            this._sprPickTips.scale = 1.0;
        }

        //珊瑚是否可点
        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
        for (let i in gameInfo.coral) {
            let roralIdx = parseInt(i) + 1;
            let winIdx = gameInfo.coral[i];

            let roralhNode = this._roralsFishList[roralIdx];
            roralhNode.getComponent(cc.Button).enabled = isPlay && winIdx == 0;
        }
    },

    async awaitOrOperate () {
        return new Promise(async (success, failed)=>{
            //提示，以及金币规律跳动
            this.setPlayPickTipsAction(true);

            for (let i=1; i<=5; i++) {
                let item = this._roralsFishList[i];
                item.off("click");
                Global.btnClickEvent(item, async ()=>{
                    Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);
                    //停止操作提示动作
                    this.setPlayPickTipsAction(false);
                    let resp = await cc.vv.gameData.reqSubGame(Global.QUEENOFSEA_MAP_RTYPE.OPERATE_SUBGAME, i);
                    if (resp.code === 200) {
                        let gameInfo = resp.data.mapInfo.gameInfo;
                        let winIdx = gameInfo.coral[i - 1];

                        //设置成不可操作
                        item.getComponent(cc.Button).enabled = false;

                        //播放拨开海草动作
                        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.select3);
                        let parrot = item.getChildByName("spineParrot");
                        parrot.active = true;
                        this.playSpine(parrot, ()=>{
                            parrot.active = false;
                        }, "animation2", false);
                        await this.awaitTime(0.3);

                        //气泡变鱼动作
                        let bubble = item.getChildByName("spineBubble");
                        bubble.active = true;
                        this.playSpine(bubble, ()=>{
                            this.playSpine(bubble, null, "animation" + BUBBLE_ANIMATION[winIdx - 1] + "_1", true);
                        }, "animation" + BUBBLE_ANIMATION[winIdx - 1], false);
                        await this.awaitTime(0.5);

                        //显示中奖
                        this._winList[winIdx].active = true;
                        await this.awaitTime(0.5);

                        if (gameInfo.winCoin > 0) {
                            Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.dead);

                            cc.find("nodeDetail/mult/spineMult_" + gameInfo.mult, this._node_main).active = true;
                            await this.awaitTime(2.0);
                            success();
                        }
                        else {
                            //提示，以及金币规律跳动
                            this.setPlayPickTipsAction(true);
                        }
                    }
                    else {
                        console.log("返回数据错误!");
                        failed();
                    }
                });
            }
        });
    },

    //显示游戏结果
    async showResult () {
        return new Promise(async (success)=>{
            this._node_win.active = true;

            let ui = this._node_win.getChildByName("ui");
            ui.scale = 0;

            let baseCoin = Global.FormatCommaNumToNum(this._lblStartPrize.getComponent(cc.Label).string);
            let mult = cc.vv.gameData.mapInfo.gameInfo.mult;

            //屏蔽collect按钮
            ui.getChildByName("btnCollect").getComponent(cc.Button).enabled = false;
            //显示公式
            this.setLabel(ui.getChildByName("lblWinCoinShow"), mult + " X " + this.convertNumToShortStr(baseCoin) + " = " + this.convertNumToShortStr(mult*baseCoin));
            //动态刷新赢取金币数
            this.rollToNumOfLabel(ui.getChildByName("lblWinCoin"), mult*baseCoin);
            //播放动画
            await this.playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);

            //把值直接设置到win上显示
            cc.vv.gameData.GetSlotsScript()._bottomScript.SetWin(mult*baseCoin);

            //开启collect按钮
            ui.getChildByName("btnCollect").getComponent(cc.Button).enabled = true;
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);

                ui.getChildByName("lblWinCoin").stopAllActions();
                this.setLabel(ui.getChildByName("lblWinCoin"), this.convertNumToShortStr(mult*baseCoin));
                this.playActions(ui, [cc.scaleTo(0.1, 1.2), cc.scaleTo(0.3, 0)]);
                success();
            }
            cc.vv.gameData.checkAutoPlay(ui.getChildByName("btnCollect"), func);
            Global.btnClickEvent(ui.getChildByName("btnCollect"), ()=>{
                ui.getChildByName("btnCollect").stopAllActions();
                func();
            }, this);
        });
    },
});
