cc.Class({
    extends: require("TheMermaid_subGameBase"),

    properties: {
        _subGameNodeName: "subGameDice",

        _lblStartPrize: null,
        _lblPickMult: null,
        _sprPickTips: null,

        _diceEffList: null,
        _winMultList: null,
        _restDiceList: null,

        _btnSpin: null,
        _spinDice: null,
        _spinBubble: null,

        _pickLeftNum: 5,
    },

    // LIFE-CYCLE CALLBACKS:

    async onLoad () {
        this._super();

        this._lblStartPrize = cc.find("nodePrizePool/theme163_game_c_2/lblStartPrize", this._node_main);
        this._lblPickMult = cc.find("nodePrizePool/theme163_game_c_3/lblPickMult", this._node_main);
        this._sprPickTips = cc.find("nodeDetail/spinTips", this._node_main);

        let nodeDetail = cc.find("nodeDetail", this._node_main);
        this._btnSpin = cc.find("btnSpin", nodeDetail);
        this._spinDice = cc.find("btnSpin/nodeDice", nodeDetail);
        this._spinBubble = cc.find("btnSpin/nodeBubble", nodeDetail);

        this._diceEffList = [];
        for (let i=1; i<=6; i++) {
            this._diceEffList[i] = cc.find("cell_" + i + "/diceSpine", nodeDetail);
        }

        this._winMultList = [];
        for (let i=1; i<=6; i++) {
            this._winMultList[i] = [];
            for (let j=1; j<=4; j++) {
                let winMultNode = cc.find("cell_" + i + "/winSpine" + j, nodeDetail);
                if (winMultNode) this._winMultList[i][j] = winMultNode;
            }
        }

        this._restDiceList = [];
        for (let i=1; i<=5; i++) {
            this._restDiceList[i] = cc.find("diceList/dice" + i, nodeDetail);
        }

        //初始化各种显示
        this.init();
    },

    init () {
        this.setLabel(this._lblPickMult,"");

        for (let diceEff of this._diceEffList) if (diceEff) diceEff.active = false;
        for (let dice of this._restDiceList) if (dice) dice.active = true;
        this.resetWinResultPanel();

        this._btnSpin.getComponent(cc.Button).enabled = true;
    },

    restoreByData () {
        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;

        this._subGameNode.active = true;
        this.setLabel(this._lblPickMult, gameInfo.mult + "X");
        this._pickLeftNum = gameInfo.restCnt;

        //显示剩余骰子
       this.refreshRestDice();

        //当前骰子
        this.playSpine(this._spinDice,null,"animation" + gameInfo.currDices[gameInfo.currDices.length - 1], false);
        this.playSpine(this._spinBubble,null,"animation1", true);

        //已中奖倍数
        this.refreshCurWinResultPanel();

        //选择提示
        this.setPlayPickTipsAction(true);
    },

    //进入游戏
    async enterGame () {
        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
        this._pickLeftNum = gameInfo.restCnt;
        this.setLabel(this._lblStartPrize, Global.FormatNumToComma(gameInfo.startPrize));

        this.init();

        return new Promise(async (success)=>{
            if (gameInfo.mult >0) {
                //断线重连
                //根据数据恢复显示
                this.restoreByData();
            }
            else {
                await this.showStart();
            }
            await this.showMain();
            await this.showResult();
            await this.exitGame();
            success();
        });
    },

    //退出游戏
    async exitGame () {
        return new Promise(async (success)=>{
            //全屏过渡
            await this.playFullScreen(1.0);
            this.setSubGameNodeVisible(false);
            success();
        });
    },

    //显示开始提示
    async showStart () {
        return new Promise(async (success)=>{
            this._subGameNode.active = true;
            this._node_start.active = true;
            this._node_start.scale = 0;
            await this.playActions(this._node_start, [cc.scaleTo(0.35, 1.5), cc.scaleTo(0.15, 1.3)]);
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);
                this.playActions(this._node_start, [cc.scaleTo(0.15, 1.5), cc.scaleTo(0.35, 0)]);
                success();
            }
            cc.vv.gameData.checkAutoPlay(this._node_start.getChildByName("btnStart"), func);
            Global.btnClickEvent(this._node_start.getChildByName("btnStart"), ()=>{
                this._node_start.getChildByName("btnStart").stopAllActions();
                func();
            }, this);
        });
    },

    //显示游戏主体
    async showMain () {
        return new Promise(async (success)=>{
            //全屏过渡
            let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
            if (gameInfo.mult <= 0) await this.playFullScreen(0.5);
            //初始化
            this._node_start.active = false;
            this._node_main.active = true;
            await this.awaitTime(0.2);
            //等待玩家选择操作
            await this.awaitOrOperate();
            //选择提示
            this.setPlayPickTipsAction(false);
            //等待
            await this.awaitTime(1.0);
            success();
        });
    },

    setPlayPickTipsAction (isPlay) {
        if (isPlay) {
            this._sprPickTips.scale = 1.0;
            this._sprPickTips.opacity = 0;
            this._sprPickTips.stopAllActions();
            this._sprPickTips.runAction(cc.sequence(cc.fadeIn(0.5), cc.callFunc(()=>{
                this._sprPickTips.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(0.5,0.8), cc.scaleTo(0.2,1.0), cc.delayTime(1.0))));
            })));
            this.playSpine(this._spinBubble,null,"animation1", true);
        }
        else {
            this._sprPickTips.stopAllActions();
            this._sprPickTips.runAction(cc.fadeOut(0.5));
        }
    },

    async awaitOrOperate () {
        return new Promise(async (success, failed)=>{
            //提示规律跳动
            this.setPlayPickTipsAction(true);

            this._btnSpin.getComponent(cc.Button).enabled = true;
            this._btnSpin.off("click");
            let func = async ()=>{
                //停止操作提示动作
                this.setPlayPickTipsAction(false);
                this._btnSpin.getComponent(cc.Button).enabled = false;
                //气泡动作
                this.playSpine(this._spinBubble, null, "animation2", false);

                let resp = await cc.vv.gameData.reqSubGame(Global.QUEENOFSEA_MAP_RTYPE.OPERATE_SUBGAME);
                if (resp.code === 200) {
                    let gameInfo = resp.data.mapInfo.gameInfo;
                    let curPoint = gameInfo.currDices[gameInfo.currDices.length - 1];
                    this._pickLeftNum = gameInfo.restCnt;

                    //剩余骰子
                    this.refreshRestDice();
                    //中骰子动作
                    Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.move);
                    this.playSpine(this._spinDice, ()=>{
                        this.playSpine(this._spinDice,null, "animation" + curPoint, false);
                    }, "animation" + curPoint + "_1", false);
                    await this.awaitTime(1.5);
                    //飞点数特效，中倍数或加次数特效，mult飞特效
                    await this.flyDicePointToResultPanel(curPoint);

                    if (this._pickLeftNum > 0) {
                        //气泡
                        this.playSpine(this._spinBubble,null,"animation3", false);
                        await this.awaitTime(0.5);
                        //提示规律跳动
                        this.setPlayPickTipsAction(true);
                        //设置可操作
                        this._btnSpin.getComponent(cc.Button).enabled = true;
                        cc.vv.gameData.checkAutoPlay(this._btnSpin, func); 
                    }
                    else {
                        success();
                    }
                }
                else {
                    console.log("返回数据错误!");
                    failed();
                }
            }
            cc.vv.gameData.checkAutoPlay(this._btnSpin, func);
            Global.btnClickEvent( this._btnSpin, async ()=>{
                this._btnSpin.stopAllActions();
                await func();
            });
        });
    },

    //刷新剩余骰子显示
    refreshRestDice () {
        for (let dice of this._restDiceList) if (dice) dice.active = false;
        for (let i=1; i<=this._pickLeftNum; i++) this._restDiceList[i].active = true;
    },

    resetWinResultPanel () {
        for (let i=1; i<=6; i++) {
            let list = this._winMultList[i];
            for (let winSpine of list) {
                if (winSpine) winSpine.active = false;
            }
        }
    },

    //刷新当前中奖区
    refreshCurWinResultPanel () {
       this.resetWinResultPanel();

        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
        let isAddSpinTimes = false;
        //播放中奖倍数
        let diceEffNode = null;
        for (let i in gameInfo.currDices) {
            let point = gameInfo.currDices[i];
            for (let idx in this._winMultList[point]) {
                let diceEff = this._winMultList[point][idx];
                if (!diceEff.active) {
                    diceEff.active = true;
                    if (parseInt(i) == this._winMultList.length - 1 && parseInt(idx) == this._winMultList[point].length - 1) {
                        isAddSpinTimes = true;
                    }
                    diceEffNode = diceEff;
                    break;
                }
            }
        }
        return {isAddTimes:isAddSpinTimes, node:diceEffNode};
    },

    //飞筛子点数到中奖倍数到结果特效
    async flyDicePointToResultPanel (curPoint) {
        return new Promise(async (success)=> {
           Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.touzi_fly);

            //飞骰子点数
            await this.playFlyEffect(this._btnSpin, this._diceEffList[curPoint]);
            //播放所中骰子特效
            this.playSpine(this._diceEffList[curPoint], null, "animation", false);
            await this.awaitTime(0.3);
            //播放中奖物品
            let data = this.refreshCurWinResultPanel();
            await this.awaitTime(0.5);
            //播放倍数
            if (!data.isAddTimes) {
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.touzi_extra);

                //飞倍数到奖池
                let targetNode = cc.find("nodePrizePool/theme163_game_c_3", this._node_main);
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.touzi_fly);
                await this.playFlyEffect(data.node, targetNode);
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.touzi_extra);

                //奖池中奖特效
                let spineNodeMult = cc.find("nodePrizePool/spineNodeMult", this._node_main);
                this.playSpine(spineNodeMult);
                await this.awaitTime(0.2);
                let mult = cc.vv.gameData.mapInfo.gameInfo.mult;
                this.setLabel(this._lblPickMult, mult? mult + "X":"");
            }
            else {
                //飞倍数到剩余点数
                await this.playFlyEffect(data.node, cc.find("nodeDetail/diceList", this._node_main));
                //刷新剩余骰子数
               this.refreshRestDice();
            }
            await this.awaitTime(0.2);

            //下一步
            success();
        });
    },

    //飞特效
    async playFlyEffect (startNode, targetNode) {
        return new Promise(async (success)=> {
            //飞骰子点数
            let startPos = this._node_main.convertToNodeSpaceAR(startNode.parent.convertToWorldSpaceAR(startNode.position));
            let targetPos = this._node_main.convertToNodeSpaceAR(targetNode.parent.convertToWorldSpaceAR(targetNode.position));
            let nodeFly = cc.find("nodeFlyMultNum", this._node_main);
            nodeFly.position = startPos;
            nodeFly.scale = 1.0;

            nodeFly.getComponent(cc.ParticleSystem).resetSystem();

            await this.playActions(nodeFly, [cc.moveTo(0.5, targetPos), cc.scaleTo(0.1, 0)]);
            //下一步
            success();
        });
    },

    //显示游戏结果
    async showResult () {
        return new Promise(async (success)=>{
            this._node_win.active = true;

            let ui = this._node_win.getChildByName("ui");
            ui.scale = 0;

            let baseCoin = Global.FormatCommaNumToNum(this._lblStartPrize.getComponent(cc.Label).string);
            let mult = cc.vv.gameData.mapInfo.gameInfo.mult;

            //屏蔽collect按钮
            ui.getChildByName("btnCollect").getComponent(cc.Button).enabled = false;
            //显示公式
            this.setLabel(ui.getChildByName("lblWinCoinShow"), mult + " X " + this.convertNumToShortStr(baseCoin) + " = " + this.convertNumToShortStr(mult*baseCoin));
            //动态刷新赢取金币数
            this.rollToNumOfLabel(ui.getChildByName("lblWinCoin"), mult*baseCoin);
            //播放动画
            await this.playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);

            //把值直接设置到win上显示
            cc.vv.gameData.GetSlotsScript()._bottomScript.SetWin(mult*baseCoin);

            //开启collect按钮
            ui.getChildByName("btnCollect").getComponent(cc.Button).enabled = true;
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);

                ui.getChildByName("lblWinCoin").stopAllActions();
                this.setLabel(ui.getChildByName("lblWinCoin"), this.convertNumToShortStr(mult*baseCoin));
                this.playActions(ui, [cc.scaleTo(0.1, 1.2), cc.scaleTo(0.3, 0)]);
                success();
            }
            cc.vv.gameData.checkAutoPlay(ui.getChildByName("btnCollect"), func)
            Global.btnClickEvent(ui.getChildByName("btnCollect"), ()=>{
                ui.getChildByName("btnCollect").stopAllActions();
                func();
            }, this);
        });
    },
});
