let MULT_ARR = ["death",16,36,60,180,600,"win_all"];
let MULT_TO_ID = {
    "0":0,
    "16":1,
    "36":2,
    "60":3,
    "180":4,
    "600":5,
    "-1":6, //win_all
};

cc.Class({
    extends: require("TheMermaid_subGameBase"),

    properties: {
        _subGameNodeName: "subGameBeke",

        _lblStartPrize: null,
        _lblPickMult: null,
        _sprPickTips: null,

        _bekeLayerListNode: null,

        _pickLeftNum: 5,
        _pickMultNum: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    async onLoad () {
        this._super();

        this._lblStartPrize = cc.find("nodePrizePool/theme163_game_c_2/lblStartPrize", this._node_main);
        this._lblPickMult = cc.find("nodePrizePool/theme163_game_c_3/lblPickMult", this._node_main);
        this._sprPickTips = cc.find("nodeList/theme163_game4_5/theme163_game4_1", this._node_main);

        this._bekeLayerListNode = cc.find("nodeList/list", this._node_main);

        //初始化各种显示
        this.init();

        //测试
        // this.enterGame({times:5, prize:32313});
    },

    init () {
        this.setLabel(this._lblPickMult, this._pickMultNum? this._pickMultNum + "X":"");

        //重置所有层
        this.resetAllLayer();
    },

    restoreByData () {
        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;

        this._subGameNode.active = true;
        this.setLabel(this._lblPickMult, gameInfo.mult + "X");
        this._pickLeftNum = 5 - gameInfo.layerChoiceId.length;

        for (let i in gameInfo.layerItemList) {
            let layer = this.getLayer(parseInt(i) + 1);
            this.showLayerRestItems(layer, gameInfo.layerChoiceId[i], gameInfo.layerItemList[i]);
            this.setItemGray(layer.getChildByName("item" + gameInfo.layerChoiceId[i]), false); //亮起选择的
        }
    },

    //进入游戏
    async enterGame () {
        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
        this._pickLeftNum = gameInfo.times || 5;
        this._pickMultNum = gameInfo.mult;
        this.setLabel(this._lblStartPrize, Global.FormatNumToComma(gameInfo.startPrize));

        this.init();

        return new Promise(async (success)=>{
            if (gameInfo.mult >0) {
                //断线重连
                //根据数据恢复显示
                this.restoreByData();
            }
            else {
                await this.showStart();
            }
            await this.showMain();
            await this.showResult();
            await this.exitGame();
            success();
        });
    },

    //退出游戏
    async exitGame () {
        return new Promise(async (success)=>{
            //全屏过渡
            await this.playFullScreen(1.0);
            this.setSubGameNodeVisible(false);
            success();
        });
    },

    //显示开始提示
    async showStart () {
        return new Promise(async (success)=>{
            this._subGameNode.active = true;
            this._node_start.active = true;
            this._node_start.scale = 0;
            await this.playActions(this._node_start, [cc.scaleTo(0.35, 1.5), cc.scaleTo(0.15, 1.3)]);
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);
                this.playActions(this._node_start, [cc.scaleTo(0.15, 1.5), cc.scaleTo(0.35, 0)]);
                success();
            }
            cc.vv.gameData.checkAutoPlay(this._node_start.getChildByName("btnStart"), func);
            Global.btnClickEvent(this._node_start.getChildByName("btnStart"), ()=>{
                this._node_start.getChildByName("btnStart").stopAllActions();
                func();
            }, this);
        });
    },

    //显示游戏主体
    async showMain () {
        return new Promise(async (success)=>{
            //全屏过渡
            let gameInfo = cc.vv.gameData.mapInfo.gameInfo;
            if (gameInfo.mult <= 0) await this.playFullScreen(0.5);
            //初始化
            this._node_start.active = false;
            this._node_main.active = true;
            await this.awaitTime(0.2);
            //等待玩家选择操作
            await this.awaitOrOperate();
            //变灰
            this.setPlayPickTipsAction(false);
            //等待
            await this.awaitTime(1.0);
            success();
        });
    },

    setPlayPickTipsAction (isPlay) {
        if (isPlay) {
            this._sprPickTips.scale = 1.0;
            this._sprPickTips.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(0.5,0.9), cc.scaleTo(0.2,1.0), cc.delayTime(2.0))));
        }
        else {
            this._sprPickTips.stopAllActions();
            this._sprPickTips.scale = 1.0;
        }
    },

    //重设某Layer
    resetLayer (layer) {
        layer.getChildByName("select").active = false;
        for (let j=1; j<=5; j++) {
            let item = layer.getChildByName("item" + j);
            item.getComponent(cc.Button).enabled = false;

            this.playSpine(item, null, "animation1", false);
            item.getChildByName("mult").active = false;
            this.playSpine(item.getChildByName("spine"), null, "animation2", false);
            this.setItemGray(item, true);
        }
    },

    //重置Layer
    resetAllLayer () {
        for (let i=1; i<=5; i++) this.resetLayer(this.getLayer(i));
    },

    //设置Layer可以操作
    setLayerEnable(layer, enable, selectId) {
        layer.getChildByName("select").active = enable;
        if (enable) this.setLayerGray(layer, false);

        for (let j=1; j<=5; j++) {
            let item = layer.getChildByName("item" + j);
            item.getComponent(cc.Button).enabled = enable;
            if (j == selectId) continue;
            this.playSpine(item, null, enable?"animation1":"animation2", false);
            this.playSpine(item.getChildByName("spine"), null, "animation2", false);
        }
    },

    //设置Layer灰色
    setLayerGray (layer, isGray, selectIdx) {
        for (let j=1; j<=5; j++) {
            let item = layer.getChildByName("item" + j);
            if (j === selectIdx) {
                this.setItemGray(item, !isGray);
            }
            else {
                this.setItemGray(item, isGray);
            }
        }
    },

    getLayer (layerIdx) {
        return  this._bekeLayerListNode.getChildByName("cell_" + layerIdx);
    },

    getLayerIdxEnable () {
        return 5 - this._pickLeftNum + 1;
    },

    getLayerItemList (data) {
        return data.layerItemList[data.layerId - 1];
    },

    getMultIdByData (data) {
        let curChoiceId = data.layerChoiceId[data.layerId - 1];
        return this.getLayerItemList(data)[curChoiceId - 1];
    },

    showLayerRestItems (layer, selectIdx, layerItemListData) {
        for (let i in layerItemListData) {
            let item = layer.getChildByName("item" + (parseInt(i) + 1));
            let mult = item.getChildByName("mult");
            mult.active = true;
            mult.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("game4_shell").getSpriteFrame("theme163_game4_result_" + MULT_ARR[MULT_TO_ID[layerItemListData[i]]]);

            if (parseInt(i) + 1 === selectIdx) {
                //显示开启状态
                this.playSpine(item.getChildByName("spine"), null, "animation4", false);
            }
        }
    },

    playShowLayerRestItems (layer, selectIdx, layerItemListData) {
        for (let j=1; j<=5; j++) {
            let item = layer.getChildByName("item" + j);
            if (j === selectIdx) {
                continue;
            }
            else {
                let mult = item.getChildByName("mult");
                mult.active = true;
                mult.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("game4_shell").getSpriteFrame("theme163_game4_result_" +  MULT_ARR[MULT_TO_ID[layerItemListData[j - 1]]]);
                this.playActions(item, [cc.scaleTo(0.3, 1.2),cc.scaleTo(0.1, 1.0)]);
            }
        }
    },

    async awaitOrOperate () {
        return new Promise(async (success, failed)=>{
            //提示，以及金币规律跳动
            this.setPlayPickTipsAction(true);
            //设置可操作层
            this.setLayerEnable(this.getLayer(this.getLayerIdxEnable()), true);

            for (let i=1; i<=5; i++) {
                let layer = this.getLayer(i);
                for (let j=1; j<=5; j++) {
                    let item = layer.getChildByName("item" + j);
                    item.off("click");
                    Global.btnClickEvent(item, async ()=>{
                        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);
                        //停止操作提示动作
                        this.setPlayPickTipsAction(false);
                        let resp = await cc.vv.gameData.reqSubGame(Global.QUEENOFSEA_MAP_RTYPE.OPERATE_SUBGAME, j);
                        if (resp.code === 200) {
                            this._pickLeftNum --;
                            let gameInfo = resp.data.mapInfo.gameInfo;
                            gameInfo.multId = this.getMultIdByData(gameInfo);

                            let curLayer = this.getLayer(this.getLayerIdxEnable() - 1);

                            Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr["select" + gameInfo.layerId]);

                            //设置可操作层
                            this.setLayerEnable(curLayer, false, gameInfo.layerChoiceId[gameInfo.layerId - 1]);
                            //开启贝壳
                            Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.select1);
                            this.playSpine(item.getChildByName("spine"), ()=>{
                                //显示开启状态
                                this.playSpine(item.getChildByName("spine"), null, "animation4", false);
                            }, "animation3", false);
                            await this.awaitTime(0.8);

                            //显示倍数
                            let mult = item.getChildByName("mult");
                            mult.active = true;
                            mult.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("game4_shell").getSpriteFrame("theme163_game4_result_" + MULT_ARR[MULT_TO_ID[gameInfo.multId]]);
                            //出现倍数缩放动作
                            mult.scale = 0;
                            await this.playActions(mult, [cc.scaleTo(0.3, 1.2),cc.scaleTo(0.1, 1.0)]);
                            //倍数飞的特效
                            if (gameInfo.multId > 0) {
                                let mult = 0;
                                if (gameInfo.multId == 6) { //WinAll
                                    for (let k=1; k<=5; k++) mult += MULT_ARR[k];
                                }
                                else {
                                    mult = MULT_ARR[MULT_TO_ID[gameInfo.multId]];
                                }
                                await this.playMultFlyEff(item, mult);
                                await this.awaitTime(0.5);
                            }

                            //设置层灰色
                            this.setLayerGray(curLayer, true, j);
                            this.playShowLayerRestItems(curLayer, j, this.getLayerItemList(gameInfo));
                            await this.awaitTime(0.5);
                            if (this._pickLeftNum > 0 && gameInfo.multId > 0) {
                                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.dead);

                                //提示，以及金币规律跳动
                                this.setPlayPickTipsAction(true);
                                //设置可操作Layer
                                this.setLayerEnable(this.getLayer(this.getLayerIdxEnable()), true);
                            }
                            else {
                                success();
                            }
                        }
                        else {
                            console.log("返回数据错误!");
                            failed();
                        }
                    });
                }
            }
        });
    },

    async playMultFlyEff (itemNode, mult) {
        return new Promise(async (success)=>{
            let beginPos = this._node_main.convertToNodeSpaceAR(itemNode.parent.convertToWorldSpaceAR(itemNode.position));

            let targetNode = cc.find("nodePrizePool/theme163_game_c_3", this._node_main);
            let targetPos = this._node_main.convertToNodeSpaceAR(targetNode.parent.convertToWorldSpaceAR(targetNode.position));

            let nodeFly = cc.find("nodeFlyMultNum", this._node_main);
            nodeFly.position = beginPos;
            nodeFly.scale = 1.0;

            nodeFly.getComponent(cc.ParticleSystem).resetSystem();

            await this.playActions(nodeFly, [cc.moveTo(0.5, targetPos), cc.scaleTo(0.1, 0)]);

            let spineNodeMult = cc.find("nodePrizePool/spineNodeMult", this._node_main);
            this.playSpine(spineNodeMult);
            await this.awaitTime(0.2);

            this._pickMultNum += mult;
            this.setLabel(this._lblPickMult, this._pickMultNum? this._pickMultNum + "X":"");

            success();
        });
    },

    setItemGray (itemNode, isGray) {
        let color = isGray?cc.Color.GRAY:cc.Color.WHITE;
        for (let subNode of itemNode.children) {
            subNode.color = color;
        }
    },

    //显示游戏结果
    async showResult () {
        return new Promise(async (success)=>{
            this._node_win.active = true;

            let ui = this._node_win.getChildByName("ui");
            ui.scale = 0;

            let baseCoin = Global.FormatCommaNumToNum(this._lblStartPrize.getComponent(cc.Label).string);

            //屏蔽collect按钮
            ui.getChildByName("btnCollect").getComponent(cc.Button).enabled = false;
            //显示公式
            this.setLabel(ui.getChildByName("lblWinCoinShow"), this._pickMultNum + " X " + this.convertNumToShortStr(baseCoin) + " = " + this.convertNumToShortStr(this._pickMultNum*baseCoin));
            //动态刷新赢取金币数
            this.rollToNumOfLabel(ui.getChildByName("lblWinCoin"), this._pickMultNum*baseCoin);
            //播放动画
            await this.playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);

            //把值直接设置到win上显示
            cc.vv.gameData.GetSlotsScript()._bottomScript.SetWin(this._pickMultNum*baseCoin);

            //开启collect按钮
            ui.getChildByName("btnCollect").getComponent(cc.Button).enabled = true;
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);

                ui.getChildByName("lblWinCoin").stopAllActions();
                this.setLabel(ui.getChildByName("lblWinCoin"), this.convertNumToShortStr(this._pickMultNum*baseCoin));
                this.playActions(ui, [cc.scaleTo(0.1, 1.2), cc.scaleTo(0.3, 0)]);
                success();
            }
            cc.vv.gameData.checkAutoPlay(ui.getChildByName("btnCollect"), func);
            Global.btnClickEvent(ui.getChildByName("btnCollect"), ()=>{
                ui.getChildByName("btnCollect").stopAllActions();
                func();
            }, this);
        });
    },
});
