cc.Class({
    extends: require("LMSlots_PrizePool_Base"),

    properties: {

    },

    start () {
        this._super()
        this.scheduleOnce(()=>{
            if(this.node.y > cc.winSize.height / 2){
                this.node.y = cc.winSize.height / 2;
            }
        },0);
    },
});
