cc.Class({
    extends: cc.Component,

    properties: {
        _soundPath: "games/TheMermaid/",
        _subGameNode: null,
        _node_main: null,
        _spineNodeLoading: null,

        _targetIdx:7, //0-65，1-90，2-45，... ，7-75
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._subGameNode = cc.find("/subGameCollectWheel", this.node);
        this._node_main = cc.find("node_main", this._subGameNode);
        this._spineNodeLoading = cc.find("spineNodeLoading", this._subGameNode);

        //初始化各种显示状态
        this.init();

        //测试
        // this.enterGame();
    },

    init () {
        this._spineNodeLoading.active = false;
        this._subGameNode.active = false;
        this._node_main.active = false;

        cc.find("spineEff1", this._node_main).active = false;
        cc.find("spineEff2", this._node_main).active = false;
        cc.find("spineEffWin", this._node_main).active = false;
    },

    //进入游戏
    async enterGame () {
        this._targetIdx = 0;

        this.init();
        await this.showMain();
        await this.showResult();
        await this.exitGame();
    },

    //退出游戏
    async exitGame () {
        //全屏过渡
        // this._spineNodeLoading.active = true;
        // this.playSpine(this._spineNodeLoading);
        await this.awaitTime(1.0);
        // this._spineNodeLoading.active = false;

        await this.playActions(this._node_main, [cc.scaleTo(0.2, 1.2), cc.scaleTo(0.5, 0)]);
        this._subGameNode.active = false;
    },

    // this.owner

    //显示游戏主体
    async showMain () {
        return new Promise(async (success)=>{
            this._subGameNode.active = true;
            await this.awaitTime(0.5);
            // //初始化
            this._node_main.active = true;
            this._node_main.scale = 0;
            cc.find("spineEff1", this._node_main).active = true;
            cc.find("spineEff2", this._node_main).active = true;
            let btn_spin = cc.find("btn_spin", this._node_main);
            btn_spin.getComponent(cc.Button).enabled = false;

           Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.wheel_in);
            await this.playActions(this._node_main, [cc.scaleTo(0.5, 1.2), cc.scaleTo(0.2, 1)]);
            //等待玩家选择操作
            await this.awaitOrOperate();

            //下一步
            success();
        });
    },

    async awaitOrOperate () {
        return new Promise(async (success)=>{
            let btn_spin = cc.find("btn_spin", this._node_main);
            btn_spin.getComponent(cc.Button).enabled = true;
            btn_spin.getComponent(cc.Button).interactable = true;
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.wheel_click);
                btn_spin.getComponent(cc.Button).interactable = false;
                success();
            }
            cc.vv.gameData.checkAutoPlay(btn_spin, func);
            Global.btnClickEvent(btn_spin, ()=>{
               btn_spin.stopAllActions();
               func();
            });
        });
    },

    //显示游戏结果(开始旋转)
    async showResult () {
        return new Promise(async (success)=>{
            cc.find("spineEff1", this._node_main).active = false;
            cc.find("spineEff2", this._node_main).active = false;

            let resp = await cc.vv.gameData.reqSubGame(Global.QUEENOFSEA_MAP_RTYPE.COLLECT_WHEEL);
            if (resp.code === 200) {
                SlotsFacade.QueenSeaCollectProgress.setCollectNum(resp.data.needCoins);

                this._targetIdx = resp.data.idx - 1;

                let rorationWheel = cc.find("rorationWheel", this._node_main);
                rorationWheel.angle = 0;

                let targetAngle = this._targetIdx*45;

                let diffAngle = targetAngle - rorationWheel.angle;

                let mRound = 10; //转动圈数

               Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.wheel);
                await this.playActions(rorationWheel, [
                    cc.rotateTo(0.5*mRound, rorationWheel.angle + 360*mRound + diffAngle).easing(cc.easeSineInOut()),
                ]);
                Global.SlotsSoundMgr.stopEffectByName(SlotsFacade.soundMgr.wheel);
               Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.wheel_stop);

                cc.find("spineEffWin", this._node_main).active = true;
                success();
            }
            else {
                AppLog.err("请求数据错误");
            }
        });
    },

    playSpine (node, endCall, animationName="animation", isLoop=false) {
        if (node) {
            node.active = true;
            node.getComponent(sp.Skeleton).setAnimation(0, animationName, isLoop);
            if (!isLoop) {
                node.getComponent(sp.Skeleton).setCompleteListener(()=>{
                    if (endCall) endCall();
                });
            }
        }
        else {
            if (endCall) endCall();
        }
    },

    playActions (node, actionsArr) {
        return new Promise((success)=>{
            actionsArr.push(cc.callFunc(()=>{
                success();
            }));

            node.active = true;
            node.runAction(cc.sequence(actionsArr));
        });
    },

    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },
});
