let MULT_ARR = [30,60,90];

cc.Class({
    extends: require("TheMermaid_subGameBase"),

    properties: {
        _subGameNodeName: "subGameGoldShip",

        _lblStartPrize: null,
        _lblPickMult: null,
        _boxItems: null,
        _sprPickTips: null,

        _pickLeftNum: 3,
        _pickMultNum: 0,
    },

    // LIFE-CYCLE CALLBACKS:

    onLoad () {
        this._super();

        this._lblStartPrize = cc.find("nodePrizePool/theme163_game_c_2/lblStartPrize", this._node_main);

        this._lblPickMult = cc.find("nodePrizePool/theme163_game_c_3/lblPickMult", this._node_main);
        this._sprPickTips = cc.find("theme163_game9_2/theme163_game9_1", this._node_main);

        this._boxItems = [];
        for (let i=1; i<=16; i++) {
            this._boxItems.push(cc.find("nodeBoxList", this._node_main).getChildByName("ItemNode" + i));
        }

        //初始化各种显示状态
        this.init();

        //测试
        // this.enterGame();
    },

    init () {
        this.setLabel(this._lblStartPrize, "");
        this.setLabel(this._lblPickMult, this._pickMultNum? this._pickMultNum + "X":"");
        for (let item of this._boxItems) {
            item.getChildByName("treasurebox").active = true;
            item.getChildByName("spine_treasurebox").active = false;
            item.getChildByName("treasurebox_open").active = false;
            item.getChildByName("sprPickMult").active  = false;
            item.getChildByName("sprPickMultDie").active  = false;
            item.getChildByName("spine_star").active = false;
            this.setBoxGray(item, false);
        }
    },

    restoreByData () {
        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;

        this._subGameNode.active = true;
        this.setLabel(this._lblPickMult, gameInfo.mult + "X");

        for (let i in gameInfo.choiceIds) {
            let id = gameInfo.choiceIds[i];
            let result = gameInfo.choiceItems[i];
            let item = this._boxItems[id - 1];

            //宝箱开启状态
            item.getChildByName("treasurebox").active = false;
            item.getChildByName("treasurebox_open").active = true;

            //显示倍数
            let sprMult = item.getChildByName("sprPickMult");
            sprMult.active = true;
            sprMult.getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("game9_treasuer").getSpriteFrame("theme163_game9_num_" + result.mult);
        }
    },

    //进入游戏
    async enterGame () {
        this.init();

        let gameInfo = cc.vv.gameData.mapInfo.gameInfo;

        this._pickMultNum = gameInfo.mult;
        this.setLabel(this._lblStartPrize, Global.FormatNumToComma(gameInfo.startPrize));

        return new Promise(async (success)=>{
            if (this._pickMultNum >0) {
                //断线重连
                //根据数据恢复显示
                this.restoreByData();
            }
            else {
                await this.showStart();
            }
            await this.showMain();
            await this.showResult();
            await this.exitGame();
            success();
        });
    },

    //退出游戏
    async exitGame () {
        return new Promise(async (success)=>{
            //全屏过渡
            await this.playFullScreen(1.0);
            this.setSubGameNodeVisible(false);
            success();
        });
    },

    //显示开始提示
    async showStart () {
        return new Promise(async (success)=>{
            this._subGameNode.active = true;
            this._node_start.active = true;
            this._node_start.scale = 0;
            await this.playActions(this._node_start, [cc.scaleTo(0.35, 1.2), cc.scaleTo(0.15, 1.0)]);
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);
                this.playActions(this._node_start, [cc.scaleTo(0.15, 1.5), cc.scaleTo(0.35, 0)]);
                success();
            }
            cc.vv.gameData.checkAutoPlay(this._node_start.getChildByName("btnStart"), func)
            Global.btnClickEvent(this._node_start.getChildByName("btnStart"), ()=>{
                this._node_start.getChildByName("btnStart").stopAllActions();
                func();
            }, this);
        });
    },

    //显示游戏主体
    async showMain () {
        return new Promise(async (success)=>{
            //全屏过渡
            await this.playFullScreen(0.5);
            //初始化
            this._node_start.active = false;
            this._node_main.active = true;
            await this.awaitTime(1.0);
            //等待玩家选择操作
            await this.awaitOrOperate();
            //变灰
            this.setPlayPickTipsAction(false);
            for (let item of this._boxItems) {
                this.setBoxGray(item, !item.getChildByName("treasurebox_open").active);
            }
            await this.awaitTime(2.0);

            success();
        });
    },

    setPlayPickTipsAction (isPlay) {
        if (isPlay) {
            this._sprPickTips.scale = 1.0;
            this._sprPickTips.runAction(cc.repeatForever(cc.sequence(cc.scaleTo(0.5,0.9), cc.scaleTo(0.2,1.0), cc.delayTime(2.0))));
            for (let item of this._boxItems) {
                if (!item.getChildByName("treasurebox_open").active) {
                    setTimeout(()=>{
                        if (!item.getChildByName("treasurebox_open").active) this.playSpine(item.getChildByName("spine_star"), null, "animation", false);
                    }, Global.random0To1() >= 0.5?500:1500);
                    item.getComponent(cc.Button).enabled = true;
                }
            }
        }
        else {
            this._sprPickTips.stopAllActions();
            this._sprPickTips.scale = 1.0;

            for (let item of this._boxItems) {
                item.getChildByName("spine_star").active = false;
                item.getComponent(cc.Button).enabled = false;
            }
        }
    },

    async awaitOrOperate () {
        return new Promise(async (success, failed)=>{
            //提示，以及金币规律跳动
            this.setPlayPickTipsAction(true);

            for (let item of this._boxItems) {
                item.off("click");

                Global.btnClickEvent(item, async ()=>{
                    Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);

                    //停止操作提示动作
                    this.setPlayPickTipsAction(false);

                    let resp = await cc.vv.gameData.reqSubGame(Global.QUEENOFSEA_MAP_RTYPE.OPERATE_SUBGAME, parseInt(item.name.substring(8,item.name.length)));
                    if (resp.code === 200) {
                        let gameInfo = resp.data.mapInfo.gameInfo;
                        let resultList = gameInfo.choiceItems;
                        let curChoiceData = resultList[resultList.length - 1];

                        //宝箱开启
                        item.getChildByName("treasurebox").active = false;
                        this.playSpine(item.getChildByName("spine_treasurebox"), ()=>{
                            item.getChildByName("spine_treasurebox").active = false;
                            item.getChildByName("treasurebox_open").active = true;
                        }, "animation2", false);
                        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.select5);

                        //显示倍数
                        if (curChoiceData.type == 1) {
                            item.getChildByName("sprPickMult").active = true;
                            item.getChildByName("sprPickMult").getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("game9_treasuer").getSpriteFrame("theme163_game9_num_" + curChoiceData.mult);

                            item.getChildByName("sprPickMult").scale = 0;
                            await this.playActions(item.getChildByName("sprPickMult"), [cc.scaleTo(0.8, 1.0)]);
                        }
                        else {
                            let name = "d" + curChoiceData.mult;
                            if (curChoiceData.type == 2) { //jackpot
                                name = "jackpot";
                            }
                            item.getChildByName("sprPickMultDie").active = true;
                            item.getChildByName("sprPickMultDie").getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("game9_treasuer").getSpriteFrame("theme163_game9_num_" + name);

                            item.getChildByName("sprPickMultDie").scale = 0;
                            await this.playActions(item.getChildByName("sprPickMultDie"), [cc.scaleTo(0.8, 1.0)]);
                        }


                        //开出倍数飞的特效
                        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.touzi_fly);
                        await this.playMultFlyEff(item, curChoiceData.mult);
                        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.touzi_extra);

                        if (curChoiceData.type != 0) { //没有鱼骨头，不结束
                            //提示，以及金币规律跳动
                            this.setPlayPickTipsAction(true);
                        }
                        else {
                            success();
                        }
                    }
                    else {
                        console.log("返回数据错误!");
                        failed();
                    }

                }, this);
            }
        });
    },

    async playMultFlyEff (itemNode, mult) {
        return new Promise(async (success)=>{
            Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.fly_mul);

            let beginPos = this._node_main.convertToNodeSpaceAR(itemNode.parent.convertToWorldSpaceAR(itemNode.position));

            let targetNode = cc.find("nodePrizePool/theme163_game_c_3", this._node_main);
            let targetPos = this._node_main.convertToNodeSpaceAR(targetNode.parent.convertToWorldSpaceAR(targetNode.position));

            let nodeFly = cc.find("nodeFlyMultNum", this._node_main);
            nodeFly.position = beginPos;
            nodeFly.scale = 1.0;

            nodeFly.getComponent(cc.ParticleSystem).resetSystem();

            await this.playActions(nodeFly, [cc.moveTo(0.5, targetPos), cc.scaleTo(0.1, 0)]);

            let spineNodeMult = cc.find("nodePrizePool/spineNodeMult", this._node_main);
            this.playSpine(spineNodeMult);
            await this.awaitTime(0.2);

            this._pickMultNum += mult;
            this.setLabel(this._lblPickMult, this._pickMultNum? this._pickMultNum + "X":"");

            success();
        });
    },

    setBoxGray (itemNode, isGray) {
        if (isGray) {
            if (Global.random0To1() > 0.6) {
                itemNode.getChildByName("sprPickMultDie").active = true;
                itemNode.getChildByName("sprPickMultDie").getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("game9_treasuer").getSpriteFrame("theme163_game9_num_d" + MULT_ARR[Math.floor(Global.random0To1()*100)%MULT_ARR.length]);
            }
            else {
                itemNode.getChildByName("sprPickMult").active = true;
                itemNode.getChildByName("sprPickMult").getComponent(cc.Sprite).spriteFrame = cc.vv.gameData.GetAtlasByName("game9_treasuer").getSpriteFrame("theme163_game9_num_" + MULT_ARR[Math.floor(Global.random0To1()*100)%MULT_ARR.length]);
            }
        }

        let color = isGray?cc.Color.GRAY:cc.Color.WHITE;
        for (let subNode of itemNode.children) {
            subNode.color = color;
        }
    },

    //显示游戏结果
    async showResult () {
        return new Promise(async (success)=>{
            this._node_win.active = true;

            let ui = this._node_win.getChildByName("ui");
            ui.scale = 0;

            let baseCoin = Global.FormatCommaNumToNum(this._lblStartPrize.getComponent(cc.Label).string);

            //屏蔽collect按钮
            ui.getChildByName("btnCollect").getComponent(cc.Button).enabled = false;
            //显示公式
            this.setLabel(ui.getChildByName("lblWinCoinShow"), this._pickMultNum + " X " + this.convertNumToShortStr(baseCoin) + " = " + this.convertNumToShortStr(this._pickMultNum*baseCoin));
            //动态刷新赢取金币数
            this.rollToNumOfLabel(ui.getChildByName("lblWinCoin"), this._pickMultNum*baseCoin);
            //播放动画
            await this.playActions(ui, [cc.scaleTo(0.3, 1.2), cc.scaleTo(0.1, 1.0)]);
            //把值直接设置到win上显示
            cc.vv.gameData.GetSlotsScript()._bottomScript.SetWin(this._pickMultNum*baseCoin);

            //开启collect按钮
            ui.getChildByName("btnCollect").getComponent(cc.Button).enabled = true;
            let func = ()=>{
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.common_click);

                ui.getChildByName("lblWinCoin").stopAllActions();
                this.setLabel(ui.getChildByName("lblWinCoin"), this.convertNumToShortStr(this._pickMultNum*baseCoin));
                this.playActions(ui, [cc.scaleTo(0.1, 1.2), cc.scaleTo(0.3, 0)]);
                success();
            }
            cc.vv.gameData.checkAutoPlay(ui.getChildByName("btnCollect"), func);
            Global.btnClickEvent(ui.getChildByName("btnCollect"), ()=>{
                ui.getChildByName("btnCollect").stopAllActions();
                func();
            }, this);
        });
    },
});
