
/**
 * 游戏主体slots
 * 
 */
cc.Class({
    extends: require("LMSlots_Slots_Base"),

    properties: {
        _popUIScript: null, //弹出UI
        _slotsCnt:1, //slots个数,免费最多3个

        _wildOpacity1_0List: null,  //记录wild变淡的数据，便于停止转动后恢复
        _bWildAnimation: false,
    },

    onLoad () {
        this._super();

        this._scatterTopAniNode = cc.find("scatter_top_ani",this.node);
    },


    start () {
        // this.scheduleOnce(this.adaptDifferentScreen.bind(this), 0.2);
    },

    //适配不同的屏幕
    adaptDifferentScreen () {
        if (this._isAdapted) return;
        this._isAdapted = true;

        let topBg = cc.find("Canvas/safe_node/LMSlots_Top/topBg");
        let topBgBtmY = topBg.convertToWorldSpaceAR(cc.v2(0, -topBg.height*0.5)).y;

        let reels_bg1 = cc.find("Canvas/safe_node/slots/reels_bg1");  //找slots最高点
        let slotsMaxHeightTopY = reels_bg1.convertToWorldSpaceAR(cc.v2(0, reels_bg1.height*2.65)).y;

        //适配奖池
        let prizePool = cc.find("Canvas/safe_node/LMSlots_PrizePool_1");
        prizePool.y = prizePool.parent.convertToNodeSpaceAR(cc.v3(0,slotsMaxHeightTopY + (topBgBtmY - slotsMaxHeightTopY)*0.5, 0)).y;

        let prizePoolSizeNode = cc.find("Canvas/safe_node/LMSlots_PrizePool_1/nodesize");
        let prizePoolSizeNodeTopY = prizePoolSizeNode.convertToWorldSpaceAR(cc.v2(0, prizePoolSizeNode.height*0.5)).y;
        // let prizePoolSizeNodeBtmY = prizePoolSizeNode.convertToWorldSpaceAR(cc.v2(0, -prizePoolSizeNode.height*0.5)).y;

        let logoSizeNode = cc.find("Canvas/safe_node/spine_logo/nodesize");
        let logoSizeNodeTopY = logoSizeNode.convertToWorldSpaceAR(cc.v2(0, logoSizeNode.height*0.5)).y;

        //适配logo
        let logo = cc.find("Canvas/safe_node/spine_logo");
        logo.y = logo.parent.convertToNodeSpaceAR(cc.v3(0,prizePoolSizeNodeTopY + logoSizeNode.height*0.7, 0)).y;

        //logo跟顶部重叠就隐藏
        // if (topBgBtmY - logoSizeNodeTopY < -20) {
            cc.find("Canvas/safe_node/spine_logo").active = false;
        // }
    },

    //重写
    RegisterEvent:function(){
        Global.registerEvent(EventId.QUEEN_ENTER_MAP,this.onRcvEvtEnterMap,this);
        Global.registerEvent(EventId.QUEEN_EXIT_MAP,this.onRcvEvtExitMap,this);
    },

    //初始化
    Init:function(){
       this._super();

        this._popUIScript = cc.find("Canvas/safe_node/node_pop_ui").addComponent("TheMermaid_Pop");

        this._slotsCnt = cc.vv.gameData._deskInfo.slotscnt || 1;
        this.showSlots();
    },

    getSlotsCount: function () {
        return this._slotsCnt || 1;
    },

    //重写
    //点击旋转按钮调用
    StartMove:function(){
        this._bStopRightnow = null
        this._gameInfo = null

        //top状态更新
        this._topScript.StartMove()

        //清除所有顶部特效
        this.ClearAllTopAni();

        //清理数据
        cc.vv.gameData.ClearOneRoundData()

        //每列转起来
        this.MoveReels(this.getCurReels());  //Changed ...

        this._wildOpacity1_0List = null; //added ...
        //设置不可点
        SlotsFacade.QueenSeaCollectProgress.setBtnsClickEnable(false);

        //设置停止时间
        //就是收到结果后，如果多少秒会开始停止
        this._stopTime = this.GetStopTime()

        //移除旧的
        SlotsFacade.QueenSeaStar.removeOldWild();
        //显示新Wild
        /*@@
        if (!this.CheckEnterFreeGame()) {
            SlotsFacade.QueenSeaStar.showNewWild();
        }
        */

        if(!cc.vv.gameData.isFreeGamesTime()){
            Global.SlotsSoundMgr.playNormalBgm();
        }
    },

    //清理一轮游戏的中奖动作
    ClearAllTopAni(){
        let reels = this.getCurReels();
        for (let reel of reels) {
            for (let i=0; i<this._row; i++) {
                let symbol = reel.GetSymbolByRow(i);
                if (symbol) {
                    symbol.ShowNormal();
                    symbol.ShowKuang(false);
                }
            }
        }

        this._topAniNode.destroyAllChildren();
        this._scatterTopAniNode.destroyAllChildren();
    },

    getCurReels () {
        let curReels = [];
        for (let i=1; i<=this._slotsCnt; i++) {
            for (let j=0; j<5; j++) {
                curReels.push(this._reels[(i-1)*5 + j]);
            }
        }
        return curReels;
    },

    addSlots () {
        if (this._slotsCnt >= 3) return;

        Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.bell);

        this._slotsCnt +=1;
        this.showSlots(true);

        SlotsFacade.QueenSeaStar.restoreByServerData();
    },

    showSlots (bPlaySpine) {
        //显示背景
        for (let i=1; i<= 3; i++) cc.find("reels_bg" + i, this.node).active = false;
        for (let i=1; i<= this._slotsCnt; i++) cc.find("reels_bg" + i, this.node).active = true;

        //显示reels
        for (let reel of this._reels) reel.node.active = false;
        for (let reel of this.getCurReels()) reel.node.active = true;

        //移动收集位置
        cc.find("collect_progress", this.node).y = cc.find("reels_bg" + this._slotsCnt, this.node).y + 170;

        //判断logo显示
        // cc.find("Canvas/safe_node/spine_logo").active = this._slotsCnt == 1;

        //播放特效
        if (bPlaySpine) {
            let spineNode = cc.find("spineAddSlots", this.node);
            spineNode.active = true;
            spineNode.position = cc.find("reels_bg" + this._slotsCnt, this.node).position;

            let spine = spineNode.getComponent(sp.Skeleton);
            spine.setAnimation(0, "animation", false);
            spine.setCompleteListener(()=>{
                spineNode.active = false;
            })
        }
    },

    //显示中奖路线
    //竞品中的显示线路是：先总，后单条循环。目前我们只显示总的
    ShowWinTrace:function(){
        if (!this._gameInfo) return;

        let allWinIdx = []

        if (this._gameInfo.mapFreeGameData && this._gameInfo.mapFreeGameData.length > 0) {
            for (let n in this._gameInfo.mapFreeGameData) {
                // traceResult
                let zjLuxian = this._gameInfo.mapFreeGameData[n].traceResult;
                for(let i = 0; i < zjLuxian.length; i++){
                    let item = zjLuxian[i]
                    for(let idx = 0; idx < item.indexs.length; idx++){
                        let posIdx = item.indexs[idx];
                        let row = Math.floor((posIdx - 1)/5);
                        let col = (posIdx - 1)%5;
                        allWinIdx[row*5*this._slotsCnt + n*5 + col + 1] = 1
                    }
                }
            }
        }
        else {
            for(let i = 0; i < this._gameInfo.zjLuXian.length; i++){
                let item = this._gameInfo.zjLuXian[i]
                for(let idx = 0; idx < item.indexs.length; idx++){
                    allWinIdx[item.indexs[idx]] = 1
                }
            }
        }

        //总
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if(symbol){
                symbol.playWinAnimation()
                symbol.ShowKuang()
            }
        }
    },

    ShowScatterWin: function () {
        if (!this._gameInfo) return;

        let allWinIdx = []

        if (this._gameInfo.mapFreeGameData && this._gameInfo.mapFreeGameData.length > 0) {
            for (let n in this._gameInfo.mapFreeGameData) {
                // scatterZJLuXian
                let scatterZJLuXian = this._gameInfo.mapFreeGameData[n].scatterResult;
                if(scatterZJLuXian && scatterZJLuXian.indexs){
                    for(let i = 0; i < scatterZJLuXian.indexs.length; i++){
                        let posIdx = scatterZJLuXian.indexs[i];
                        let row = Math.floor((posIdx - 1)/5);
                        let col = (posIdx - 1)%5;
                        allWinIdx[row*5*this._slotsCnt + n*5 + col + 1] = 1
                    }
                }
            }
        }
        else {
            if(this._gameInfo.scatterZJLuXian && this._gameInfo.scatterZJLuXian.indexs){
                for(let i = 0; i < this._gameInfo.scatterZJLuXian.indexs.length; i++){
                    let val = this._gameInfo.scatterZJLuXian.indexs[i];
                    allWinIdx[val] = 1
                }
            }
        }

        //总
        let cfg = cc.vv.gameData.getGameCfg()
        for (const key in allWinIdx) {
            let symbol = this.GetSymbolByIdx(Number(key))
            if(symbol) {
                //播放新的放到上面层
                let newSymbol = cc.instantiate(symbol.node).getComponent(cfg.scripts.Symbols);
                newSymbol.node.parent = this._scatterTopAniNode;
                newSymbol.node.active = true;
                newSymbol.node.position = this._scatterTopAniNode.convertToNodeSpaceAR(symbol.node.convertToWorldSpaceAR(cc.v2(0,0)));
                newSymbol.setTopAniNode(this._scatterTopAniNode);
                newSymbol.playWinAnimation();

                //把原来符号的显示内容隐藏
                symbol._showNode.active = false;
            }
        }
    },

    SetSlotsResult:function(msg){
        let cardsList = msg.resultCards;
        //整理cards
        if (msg.mapFreeGameData && msg.mapFreeGameData.length > 0) {
            cardsList = [];
            for (let i=0; i<this._row; i++) {
                for (let slotResult of msg.mapFreeGameData) {
                    for (let j=0; j<5; j++) {
                        cardsList.push(slotResult.cards[i*5+j]);
                    }
                }
            }
        }

        let reelResults = []
        let aCol = 5*this._slotsCnt;
        for(let i = 0;i < cardsList.length; i++){
            let row = Math.floor(i / aCol)
            let col = i % aCol
            //配置中有没有这个元素
            if(this._cfg.symbol[cardsList[i]]){
                let res = {}
                res.sid = cardsList[i]
                res.data = this.GetBonusData(res.sid, col);
                if(!reelResults[col]) reelResults[col] = []
                reelResults[col].unshift(res)
            }
        }
        for(let j = 0; j < 5*this._slotsCnt; j++){
            let item = this._reels[j]
            let reelRes = reelResults[j]
            item.SetResult(reelRes)
        }
    },

    GetBonusData (sid, col) {
        if (sid == 13) {
            //@@let starFishInfo = cc.vv.gameData.starFishInfo;
            //@@let info = cc.vv.gameData.isFreeGamesTime()?starFishInfo.inFree:starFishInfo.inBase;
            //@@if (info.num[col - 2] == 2) {  //第二个海星才播放停止动画
                return {bPlayEff:true};
            //@@}
        }
    },

    //重写：小游戏取的数据不一样
    onMsgSpine:function(msg){
        this._gameInfo = msg

        this.SetSlotsResult(msg)

        let cards = msg.resultCards
        if (msg.mapFreeGameData && msg.mapFreeGameData.length > 0) {
            cards = msg.mapFreeGameData[0].cards;
        }
        this.SetReelStateInfo(cards)
    },

    //根据服务端序号获取本地的symbol
    GetSymbolByIdx:function(idx){
        let selfCol = 5*this._slotsCnt;
        let col = (idx - 1) % selfCol
        let row = this._row - Math.floor((idx -1)/selfCol) -1
        return this._reels[col].GetSymbolByRow(row)
    },

    showCollectEnegy () {
      return new Promise(async (success)=>{
          //收集能量
          let progressData = cc.vv.gameData.progressData;
          if(progressData) {
              let posArr = [];
              this._reels.forEach(reel=>{
                  if (reel.node.active) {
                      for (let i=0; i<this._row; i++) {
                          let symbol = reel.GetSymbolByRow(i);
                          if (symbol.GetShowId() == cc.vv.gameData.getGameCfg().collectId) {
                              posArr.push(symbol.node.parent.convertToWorldSpaceAR(symbol.node.position));
                          }
                      }
                  }
              });

              if (posArr.length > 0) {
                  await SlotsFacade.QueenSeaCollectProgress.collectEnergy(posArr, progressData.totalCnt/progressData.needCnt);
              }
          }
          //下一步
          success();
      });
    },

    //单列停止
    //colIdx:0开始
    //回弹动作执行之前的停止时机
    async OnReelSpinEnd(colIdx){
        //Wild显示，动画需变成透明
        let nextColId = colIdx+1;
        let wildslotsIdx = Math.floor(nextColId/5);
        let wildcolIdx = nextColId%5 - 2;
        /*@@
        if (wildcolIdx >= 0 && this.isExistSpecialSymbolOfReel(nextColId)) {
            SlotsFacade.QueenSeaStar.playWildReel(wildslotsIdx, wildcolIdx, Global.WILD_ANIMTION.OPACITY_1_0, false);
            this._wildOpacity1_0List = this._wildOpacity1_0List || [];
            this._wildOpacity1_0List.push({slotsIdx:wildslotsIdx, colIdx:wildcolIdx});
        }
        */
        if (wildcolIdx >= 0 && this.isExistBonusSymbolOfReel(nextColId)) {
            this._bWildAnimation = true;
            await this.awaitTime(0.75);
            SlotsFacade.QueenSeaStar.playWildReel(wildslotsIdx, wildcolIdx, Global.WILD_ANIMTION.OPACITY_0_1, false, ()=>{
                SlotsFacade.QueenSeaStar.playWildReel(wildslotsIdx, wildcolIdx, Global.WILD_ANIMTION.NOMARL_LOOP, true);
            });
        }
    },

    isExistBonusSymbolOfReel (colIdx) {
        let bExist = false;
        let reel = this._reels[colIdx];
        if (reel) {
            for (let sdata of reel._originResult) {
                if (sdata && sdata.sid == 13) {
                    bExist = true;
                    break;
                }
            }
        }
        return bExist;
    },

    //检测是否存在海星bonus，宝箱scatter
    isExistSpecialSymbolOfReel (colIdx) {
        let bExist = false;
        let reel = this._reels[colIdx];
        if (reel) {
            for (let sdata of reel._originResult) {
                if (sdata && (sdata.sid == 2 || sdata.sid == 13)) {
                    bExist = true;
                    break;
                }
            }
        }
        return bExist;
    },

    //设置reel旋转的状态；
    //是否加速框；
    //是否加速旋转
    //是否停止音效；
    //是否播放背景特效
    SetReelStateInfo:function(cards){
        if (!this._cfg.reelStateInfo) {
            return;
        }
        let reelResults = []
        for(let i = 0;i < cards.length; i++){
            let id = cards[i]
            let col = i % 5
            if(!reelResults[col]) reelResults[col] = []
            reelResults[col].push(id)
        }

        for (let info of this._cfg.reelStateInfo) {
            let stateInfo = Global.copy(info);
            stateInfo.isStop = false
            stateInfo.isAnt = false

            let triggerCount = stateInfo.mini
            let countsConfig = Global.copy(stateInfo.counts);
            let haveCount = 0

            for(let i = 0; i < reelResults.length; i++){
                let item = this._reels[i]
                let reelRes = reelResults[i]
                stateInfo.isStop = false
                stateInfo.isAnt = false
                if (haveCount >= triggerCount-1 && stateInfo.counts[i] > 0) {  //满足条件 需要播放加速框
                    stateInfo.isAnt = true
                }
                let reelCountOfID = reelRes.reduce((a, v) => stateInfo.id.includes(v) ? a + 1 : a + 0, 0);
                haveCount +=  reelCountOfID
                countsConfig.shift()
                let remainingCount = (countsConfig.length > 0 ? countsConfig.reduce((x,y)=>x+y):0) + haveCount
                if (reelCountOfID > 0 && remainingCount >= triggerCount) {  //满足条件 播放停止动画和停止音效
                    stateInfo.isStop = true
                }
                item.AddReelStateInfo(Global.copy(stateInfo))
            }
        }
    },

    //配置了加速节点才显示，如果点击了立即停止(_bStopRightnow)也不显示了。
    //每列停止后，会自动隐藏加速节点
    DoCheckReelAnti:function(colIdx){
        if(!this._bStopRightnow){
            let isPlayAnit = false
            for(let i = 0; i < 5*this._slotsCnt; i++){
                let idx = this._reels[i].GetReelIdx()
                if(idx == colIdx+1){
                    isPlayAnit = this._reels[i].playAntiAnimation()

                    //Wild显示，动画需变成透明
                    let nextColId = colIdx+1;
                    let wildslotsIdx = Math.floor(nextColId/5);
                    let wildcolIdx = nextColId%5 - 2;
                    if (wildcolIdx >= 0 && nextColId < 5  && isPlayAnit) { //只有下面5个才会显示
                        /*@@
                        SlotsFacade.QueenSeaStar.playWildReel(wildslotsIdx, wildcolIdx, Global.WILD_ANIMTION.OPACITY_1_0, false);
                        this._wildOpacity1_0List = this._wildOpacity1_0List || [];
                        this._wildOpacity1_0List.push({slotsIdx:wildslotsIdx, colIdx:wildcolIdx});
                        */
                    }
                }
                if(idx > colIdx && isPlayAnit){//加速显示的时候，多转1s
                    let nAddSpeedTime = cc.vv.gameData.getGameCfg().AddAntiTime || 1
                    this._reels[i].AddDelayTime(nAddSpeedTime)
                }
            }
        }
    },

    //重写：显示bonus中奖
    async OnSpinEnd () {
        //隐藏所有加速框，防止因立即停止，导致加速框残留问题
        for (let reel of this._reels) reel.ShowAntiEffect(false);

        if (this._bWildAnimation) {
            this._bWildAnimation = false;
            await this.awaitTime(0.75);
        }

        //是否中奖,中奖了就不能开始下一局
        // let bHit = this.CheckSpecialReward()
        // if(bHit){ //所有按钮状态显示成灰太
            this._bottomScript.ShowBtnsByState("moveing_1")
        // }
        // else{//不中奖
        //     this._bottomScript.ShowBtnsByState("stoped");
        // }

        if (cc.vv.gameData.isOpenCollectProgress()) {
            await this.showCollectEnegy();
        }
        //显示中奖路线
        this.ShowWinTrace()
        //显示底部赢钱
        await this.playBottomWin();

        // // 播放海星收集
        // let symbolsArr = [];
        // for (let j=2; j>=0; j--) for (let i=0; i<5; i++) symbolsArr.push(this._reels[i].GetSymbolByRow(j));
        // SlotsFacade.QueenSeaStar.playStarFish(symbolsArr);

        //把Wild因为显示Scatter，而变透明的重新恢复正常显示
        /*@@
        if (this._wildOpacity1_0List && this._wildOpacity1_0List.length > 0) {
            await this.awaitTime(1.0);
            for (let d of this._wildOpacity1_0List) {
                SlotsFacade.QueenSeaStar.playWildReel(d.slotsIdx, d.colIdx, Global.WILD_ANIMTION.OPACITY_0_1, false, ()=>{
                    SlotsFacade.QueenSeaStar.playWildReel(d.slotsIdx, d.colIdx, Global.WILD_ANIMTION.NOMARL_LOOP, true);
                });
            }
        }
        */

        //检测是否进入子游戏
        if (this.CheckTriggerMapSubGame()) {
            await this.awaitTime(0.5);
            this._isSpinEndEnterMap = true;
            this._bottomScript.SetWin(0); //清除赢取金币
            await SlotsFacade.QueenSeaMap.enterMap(false, true);

            //显示底部赢钱
            if (SlotsFacade.QueenSeaMap.isTriggerSubGame()) {
                await this.playBottomWin(this._bottomScript.getCurrentWin());
            }

            if (cc.vv.gameData.isFreeGamesTime()) this._bottomScript.SetWin(cc.vv.gameData.GetGameTotalFreeWin());
        }

        //检测是否触发免费游戏
        if (this.CheckEnterFreeGame()) {
            Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.bell);

            //播放中奖Scatter
            this.ShowScatterWin()
            await this.awaitTime(2.0);

            Global.SlotsSoundMgr.stopBgm();
            //显示触发次数提示
            Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.free_dialog_start_show);
            await this._popUIScript.showFreeCount();
            //显示免费
            this.scheduleOnce(()=>{
                //海星收集恢复正常
                SlotsFacade.QueenSeaStar.Init();
                this.showFreeGames();
                //备份
                this.Backup();
            }, 0.5);
            //显示过渡页
            await this._popUIScript.showLoadingPage();
        }
        else if (this.CheckFreeGameFinish()) { //免费游戏是否结束
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.free_dialog_collect_show);
            //显示触发次数提示
            await this._popUIScript.showSttlDialog();
            //隐藏免费
            this.scheduleOnce(()=>{
                //清除所有顶部特效
                this.ClearAllTopAni();

                this._slotsCnt =1;
                this.showSlots(false);
                this.showFreeGames();

                Global.SlotsSoundMgr.stopBgm();

                //恢复备份
                this.Resume();

                //初始化
                cc.vv.gameData._gameInfo.slotscnt = this._slotsCnt;
                //海星收集恢复正常
                SlotsFacade.QueenSeaStar.restoreByServerData();
            }, 0.5);
            //显示过渡页
            await this._popUIScript.showLoadingPage();

            //显示底部赢钱
            await this.playBottomWin(null, true);
        }
        else {
            // 判断是否是免费 ...
            // 免费轮盘添加 显示提示
            if (cc.vv.gameData._gameInfo.slotsadd) {
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.free_dialog_more_show);

                //播放中奖Scatter
                this.ShowScatterWin();
                await this.awaitTime(0.5);
                //显示过渡页
                await this._popUIScript.showExtraFreeGameTip();
                //添加卷轴
                this.addSlots();
                await this.awaitTime(1.5);
            }
        }
        // await this.awaitTime(0.5);

        //设置不可点
        SlotsFacade.QueenSeaCollectProgress.setBtnsClickEnable(true);
        //下一局
        this.CanDoNextRound();

    },

    async playBottomWin (win, isShowFreeBigWin) {
        return new Promise((success)=>{
            let nWin = win || cc.vv.gameData.GetGameWin();

            let nTotal = nWin
            let updateAllCoin = true;
            if(!win && cc.vv.gameData.GetTotalFree() > 0 && cc.vv.gameData.GetTotalFree() != cc.vv.gameData.GetFreeTime()){
                nTotal = cc.vv.gameData.GetGameTotalFreeWin()
                updateAllCoin = cc.vv.gameData.GetFreeTime() == 0;
            }

            if (isShowFreeBigWin) {
                nWin = cc.vv.gameData.GetGameTotalFreeWin()
                nTotal = nWin
                updateAllCoin = true;
            }

            if (nWin > 0) {
                this.ShowBottomWin(nWin,nTotal,updateAllCoin,async ()=>{
                    success();
                });
            }
            else {
                success();
            }
        });
    },

    awaitTime (time) {
        return new Promise((success)=>{
            this.scheduleOnce(()=>{
                success()
            },time);
        });
    },

    //结束后的特殊中奖逻辑，有的中奖，不能马上点spin,需要有过渡动画。
    //根据各自需求重写
    CheckSpecialReward:function(){
        return this.CheckEnterFreeGame() || this.CheckFreeGameFinish() || this.CheckTriggerMapSubGame() || this.CheckSeaStarShow()
    },

    //检查是否触发免费
    CheckEnterFreeGame:function(){
        return cc.vv.gameData.isTriggerFreeGames();
    },

    //检查是否免费结束
    CheckFreeGameFinish:function(){
        return cc.vv.gameData.isFinishFreeGames();
    },

    //检查触发地图游戏
    CheckTriggerMapSubGame: function(){
        return cc.vv.gameData.isEnterMapGames();
    },

    //检测是否有海星相关动作
    CheckSeaStarShow: function () {
        return SlotsFacade.QueenSeaStar.isPlayAnimtion();
    },
    
    //转场动画
    ShowTranstion:function(pEndCall){
        // let self = this
        let tranNode = cc.find("Canvas/safe_node/translate_node")
        tranNode.active = true
        let ani = tranNode.getComponent(sp.Skeleton)
        ani.setAnimation(0,"animation",false)
        let delayCall = function(){
            if(pEndCall){
                pEndCall()
            }

        }
        this.scheduleOnce(delayCall,0.5)
    },

    //重写
    ReconnectShow:function(){
        //是否进入地图游戏
        if (!this.CheckTriggerMapSubGame()) {
            if (this.showFreeGames()) {
                //所有按钮状态显示成灰太
                this._bottomScript.ShowBtnsByState("moveing_1");
               this.scheduleOnce(()=>{
                   this.CanDoNextRound();
               }, 1.0);
            }
        }
    },

    showFreeGames () {//免费
        let total = cc.vv.gameData.GetTotalFree()
        let rest = cc.vv.gameData.GetFreeTime()
        if(rest > 0){
            Global.SlotsSoundMgr.stopBgm();
            Global.SlotsSoundMgr.playBgm(SlotsFacade.soundMgr.freegame_bgm);

            this._bottomScript.ShowFreeModel(true,total-rest,total)
            let nTotal = cc.vv.gameData.GetTotalFreeWin()
            if (nTotal > 0) this._bottomScript.SetWin(nTotal);
            this._ShowGameBg(true)
            return true;
        }
        else {
            // Global.SlotsSoundMgr.stopBgm();

            cc.vv.gameData.SetTotalFree(0);
            this._bottomScript.ShowFreeModel(false);
            this._ShowGameBg(false)
            return false;
        }
    },

    _ShowGameBg:function(bFree){
        let normalBg = cc.find("Canvas/safe_node/spr_bg_normal")
        let normalFree = cc.find("Canvas/safe_node/spr_bg_free")
        normalBg.active = !bFree
        normalFree.active = bFree
    },

    onRcvEvtEnterMap() {
        //所有按钮状态显示成灰太
        this._bottomScript.ShowBtnsByState("moveing_1");
        this._topScript.SetBackLobby(false);
    },

    async onRcvEvtExitMap(){
        if (!this._isSpinEndEnterMap) { //断线重连流程才会走下面流程
            //显示免费
            this.showFreeGames()

            //显示底部赢钱
            if (SlotsFacade.QueenSeaMap.isTriggerSubGame()){
                await this.playBottomWin(this._bottomScript.getCurrentWin());
            }

            //开始下一局
            this.CanDoNextRound();
        }
        this._isSpinEndEnterMap = false;
        this._bottomScript.ShowBtnsByState("idle");
        this._topScript.SetBackLobby(true);
    },
});
