let WILD_ANIMTION = {
    APPEAR:1,  //出现
    OPACITY_0_1:2,  //透明 0-1
    NOMARL_LOOP: 3, //正常循环显示
    OPACITY_1_0:4,  //透明 1-0
    DISAPPEAR:5, //消失
};

let gv = require("GlobalVar");
gv.WILD_ANIMTION = WILD_ANIMTION;


