    // LIFE-CYCLE CALLBACKS:
    onLoad () {
        this._starList = [];
        for (let i=1; i<=6; i++) {
            let col = Math.floor((i-1)/2);
            this._starList[col] = this._starList[col] || [];

            let star = cc.find("theme163_collect_2_3_" + i, this.node);
            star.active = false;
            this._starList[col].push(star);

            cc.find("spineFire", star).active = false;
        }

        this._wildSlotsList = [];
        for (let i=1; i<=3; i++) {
            let slotsNode = cc.find("slots" + i, this.node);
            slotsNode.active = true;

            let wildFrameList = [];
            for (let j=1; j<=3; j++) {
                let wildFrame = cc.find("spineReelWildFrame" + j, slotsNode);
                wildFrame.active = false;
                wildFrameList.push(wildFrame);
            }

            let wildList = [];
            for (let j=1; j<=3; j++) {
                let wild = cc.find("spineReelWild" + j, slotsNode);
                wild.active = false;
                wildList.push(wild);
            }

            this._wildSlotsList.push({node:slotsNode, wildFrameList:wildFrameList, wildList:wildList});
        }

        this._spineFlyStar = cc.find("spineFlySeaStar", this.node);
        this._spineFlyStar.active = false;

        this._spineStarFire = cc.find("spineSeaStarFire", this.node);
        this._spineStarFire.active = false;

        this._particleFly = cc.find("particleFly", this.node);
        this._particleFly.active = false;
    },

    start () {
        //考虑断线重连
        this.restoreByServerData();
    },

    Init () {
        //隐藏所有星星
        for (let v of this._starList) for (let vv of v) vv.active = false;

        //隐藏所有wildFrame，wild
        for (let v of this._wildSlotsList) {
            for (let vv of v.wildFrameList) vv.active = false;
            for (let vv of v.wildList) vv.active = false;
        }
    },

