    //显示新增加的wild
    async showNewWild () {
        if (cc.vv.gameData._gameInfo){ //考虑第一局进来，不存在_gameInfo数据
            let starFishInfo = cc.vv.gameData.starFishInfo;
            let currWildCols = starFishInfo.currWildCols; //新触发的列

            //新触发的列，显示Frame
            if (currWildCols && currWildCols.length) {
                Global.SlotsSoundMgr.playEffect(SlotsFacade.soundMgr.reel_up);

                let slotCnt = cc.vv.gameData.GetSlotsScript().getSlotsCount();
                let dataArr = [];
                for (let serverColIdx of currWildCols) {
                    let colIdx = serverColIdx - 3;
                    for (let j=0; j<slotCnt; j++) {
                        this.playWildReel(j, colIdx, WILD_ANIMTION.APPEAR, false, ()=>{
                            let wildFrame = this._wildSlotsList[j].wildFrameList[colIdx];
                            wildFrame.active = false; //隐藏

                            this.playWildReel(j, colIdx, WILD_ANIMTION.NOMARL_LOOP, true);
                        });
                    }
                }
                await this.playNewWildFrame(dataArr);
            }
        }
    },

