/**
 * 游戏自己的gamedata
 */
cc.Class({
    extends: require("LMSlots_GameData_Base"),

    properties: {
        mapInfo   : null,   // 收集游戏相关信息
        progressData  : null,   // 能量数据

        needBet   : 0,      //需要押注
    },

    //deskInfo进入游戏获得的服务端数据
    init(deskInfo,gameId,gameJackpot){
       this._super(deskInfo,gameId,gameJackpot);

        this.mapInfo = this._deskInfo.mapInfo;
        this.progressData = this.mapInfo.progressData;
        this.needBet = this.mapInfo.needBet;

        //@@ 功能调整，startFishInfo改成wildCols，出现海星的列直接变成wild列，不再收集海星
        //@@this.starFishInfo = this._deskInfo.starFishInfo;
    },

    //本轮旋转赢钱
    GetGameWin:function(){
        if (!this._gameInfo) return 0;
        let winCoin =  this._gameInfo.wincoin
        if (this._gameInfo.mapFreeGameData && this._gameInfo.mapFreeGameData.length > 0) {
            winCoin = 0;
            for (let d of this._gameInfo.mapFreeGameData) {
                winCoin += d.winCoin;
            }
        }
        return winCoin;
    },

    GetMaxBetIdx() {
      return this._deskInfo.mults.length;
    },

    SetSubGameData:function(data){
        this._subGame = data
    },

    GetSubGameData:function(){
        return this._subGame
    },

    //免费游戏总共赢钱.当前局数免费赢钱
    GetGameTotalFreeWin:function(){
        if (!this._gameInfo) return 0;
        return this._gameInfo.freeWinCoin;
    },


    //是否进入地图
    isEnterMapGames:function(){
        return cc.vv.gameData.mapInfo.state != Global.QUEENOFSEA_MAP_STATE.COLLECT_ENERGY;
    },

    //是否触发免费游戏
    isTriggerFreeGames: function () {
        return this._deskInfo.restFreeCount > 0 && this._deskInfo.restFreeCount == this._deskInfo.allFreeCount;
    },

    //是否免费游戏结束
    isFinishFreeGames: function () {
        return this._deskInfo.restFreeCount == 0 && this._deskInfo.allFreeCount > 0;
    },

    //是否在免费游戏中
    isFreeGamesTime: function () {
        return this._deskInfo.allFreeCount > 0 && this._deskInfo.restFreeCount < this._deskInfo.allFreeCount;
    },

    isOpenCollectProgress: function () {
        return this.GetBetIdx() >= this.needBet;
    },

    //转一次
    ReqSpin:function(curBetIdx){
        let req = {c: MsgId.SLOT_START};
        req.betIndex = curBetIdx;
        req.gameid = this._gameId;  //添加
        cc.vv.NetManager.send(req,true);
    },

    OnRcvNetSpine:function(msg){
        if(msg.code == 200){
            // msg = {"zjLuXian":[],"c":44,"code":200,"betcoin":1500000,"freeResult":{"freeInfo":{"idxs":[3,10,14],"scatterIdx":[3,10,14],"scatter":2,"freeCnt":10,"addMult":1},"triFreeCnt":1},"wildCols":[5,3,4],"mapInfo":{"progressData":{"totalCnt":3,"totalCoin":4500000,"needCnt":60,"curCoin":2},"totalCoin":32496000,"freeInfo":{"idx":1},"state":0,"gameInfo":[],"nextGame":4,"restStep":6,"totalCnt":23,"completeGame":[5,4,3],"prevGame":3},"resultCards":[4,12,2,8,7,4,12,5,4,2,3,10,1,2,1],"allFreeCnt":10,"addMult":1,"lastBetCoin":8847691110,"coin":8847691110,"mults":[10000,20000,50000,100000,150000,200000,300000,400000,500000,600000,700000,800000,900000,1000000,1500000,2000000,2500000,3000000,3500000,4000000,4500000,5000000,6000000,7000000,8000000],"spcode":200,"pooljp":0,"spEffect":{"wincoin":1500000,"kind":0},"scatterZJLuXian":{"mult":1,"coin":1500000,"indexs":[3,10,14]},"nextBetLine":{"spcode":500},"spLuXian":0,"freeCnt":10,"wincoin":1500000,"freeWinCoin":1500000,"subGameInfo":{"isMustJoin":-1,"subGamid":-1},"debugfree":{"freerate":250,"threshold":80,"random_threshold":10,"bonusControl":20}}

            if (msg.spcode && msg.spcode==967) {
                cc.vv.FloatTip.show("流程错误！！！");
                return;
            }

            this.mapInfo = msg.mapInfo; //更新mapInfo
            this.progressData = msg.mapInfo.progressData;
            //@@this.starFishInfo = msg.starFishInfo;
            this.wildCols = msg.wildCols;
            this._super(msg);
        }
    },

    /**
     * 请求子游戏数据51
     * @param rType 1选择子游戏 2转盘收集数 3子游戏选择
     */
    reqSubGame(rType, choiceId) {
        return new Promise(res=>{
            let req = {
                c:MsgId.SLOT_SUBGAME_DATA,
                gameid:this._gameId,
                data:{rtype:rType}
            };
            if (rType == 1) req.data.choiceGameId = choiceId;
            if (rType == 3) req.data.choiceId = choiceId;

            let resp = (msg)=>{
                cc.vv.NetManager.unregisterMsg(MsgId.SLOT_SUBGAME_DATA, resp, false, this);
                console.log("<<<< reqSubGame-resp: ", msg)

                if (msg.code === 200) { //更新mapInfo
                    if (msg.data.mapInfo) this.mapInfo = msg.data.mapInfo;
                }
                res(msg);
            }
            cc.vv.NetManager.registerMsg(MsgId.SLOT_SUBGAME_DATA, resp, this);
            cc.vv.NetManager.send(req, true);
        });
    },

});
